I SUGGEST THIS
Secret Code Matching System - Like eFootball's private match system, users generate a unique code to connect with specific friends
Shared Session Space - A private collaborative environment where only invited users can see and interact
Real-time Collaboration - Both users can upload content, chat, share pictures in this session
Context-Aware AI Assistant - An AI that monitors the conversation thread and can provide relevant suggestions when asked
Privacy Controls - Users can disconnect/end the linkage whenever they want

SO IMPLEMENT A SESSION AND USE THIS CODE:

import React, { useState, useEffect, useRef } from 'react';
import { MessageCircle, Send, Bot, Upload, X, Copy, Check, Users, Sparkles } from 'lucide-react';

export default function CollaborativeSession() {
  const [currentView, setCurrentView] = useState('home'); // home, create, join, session
  const [sessionCode, setSessionCode] = useState('');
  const [inputCode, setInputCode] = useState('');
  const [username, setUsername] = useState('');
  const [sessionData, setSessionData] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [isAIThinking, setIsAIThinking] = useState(false);
  const [copied, setCopied] = useState(false);
  const messagesEndRef = useRef(null);
  const fileInputRef = useRef(null);

  // Generate unique session code
  const generateCode = () => {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    let code = '';
    for (let i = 0; i < 6; i++) {
      code += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return code;
  };

  // Load session data from storage
  const loadSession = async (code) => {
    try {
      const result = await window.storage.get(`session:${code}`, true);
      if (result) {
        return JSON.parse(result.value);
      }
      return null;
    } catch (error) {
      return null;
    }
  };

  // Save session data to storage
  const saveSession = async (code, data) => {
    try {
      await window.storage.set(`session:${code}`, JSON.stringify(data), true);
    } catch (error) {
      console.error('Failed to save session:', error);
    }
  };

  // Create new session
  const createSession = async () => {
    if (!username.trim()) {
      alert('Please enter your name');
      return;
    }

    const code = generateCode();
    const newSession = {
      code,
      creator: username,
      participants: [username],
      messages: [],
      createdAt: Date.now()
    };

    await saveSession(code, newSession);
    setSessionCode(code);
    setSessionData(newSession);
    setMessages([]);
    setCurrentView('session');
  };

  // Join existing session
  const joinSession = async () => {
    if (!username.trim()) {
      alert('Please enter your name');
      return;
    }

    if (!inputCode.trim()) {
      alert('Please enter session code');
      return;
    }

    const session = await loadSession(inputCode.toUpperCase());

    if (!session) {
      alert('Session not found. Please check the code.');
      return;
    }

    // Add participant if not already in session
    if (!session.participants.includes(username)) {
      session.participants.push(username);
      await saveSession(inputCode.toUpperCase(), session);
    }

    setSessionCode(inputCode.toUpperCase());
    setSessionData(session);
    setMessages(session.messages || []);
    setCurrentView('session');
  };

  // Send message
  const sendMessage = async () => {
    if (!newMessage.trim()) return;

    const message = {
      id: Date.now(),
      sender: username,
      text: newMessage,
      timestamp: Date.now(),
      type: 'text'
    };

    const updatedMessages = [...messages, message];
    setMessages(updatedMessages);
    setNewMessage('');

    // Save to storage
    const session = await loadSession(sessionCode);
    if (session) {
      session.messages = updatedMessages;
      await saveSession(sessionCode, session);
    }

    scrollToBottom();
  };

  // Upload image
  const handleImageUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onloadend = async () => {
      const message = {
        id: Date.now(),
        sender: username,
        text: '',
        image: reader.result,
        timestamp: Date.now(),
        type: 'image'
      };

      const updatedMessages = [...messages, message];
      setMessages(updatedMessages);

      // Save to storage
      const session = await loadSession(sessionCode);
      if (session) {
        session.messages = updatedMessages;
        await saveSession(sessionCode, session);
      }

      scrollToBottom();
    };
    reader.readAsDataURL(file);
  };

  // Ask AI for help
  const askAI = async () => {
    if (messages.length === 0) {
      alert('No conversation yet. Chat with your partner first, then ask AI for help!');
      return;
    }

    setIsAIThinking(true);

    // Build conversation context for AI
    const conversationContext = messages
      .filter(m => m.type === 'text')
      .map(m => `${m.sender}: ${m.text}`)
      .join('\n');

    try {
      const response = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          model: 'claude-sonnet-4-20250514',
          max_tokens: 1000,
          messages: [
            {
              role: 'user',
              content: `You are an AI study assistant helping students who are collaborating. You've been monitoring their conversation and they need your help.

Here's their conversation so far:
${conversationContext}

Based on their discussion, provide helpful suggestions, explanations, or answers to help them move forward with their study session. Be specific and relevant to what they've been discussing.`
            }
          ]
        })
      });

      const data = await response.json();
      const aiResponse = data.content[0].text;

      const aiMessage = {
        id: Date.now(),
        sender: 'AI Assistant',
        text: aiResponse,
        timestamp: Date.now(),
        type: 'ai'
      };

      const updatedMessages = [...messages, aiMessage];
      setMessages(updatedMessages);

      // Save to storage
      const session = await loadSession(sessionCode);
      if (session) {
        session.messages = updatedMessages;
        await saveSession(sessionCode, session);
      }

      scrollToBottom();
    } catch (error) {
      console.error('AI Error:', error);
      alert('Failed to get AI response. Please try again.');
    } finally {
      setIsAIThinking(false);
    }
  };

  // Copy code to clipboard
  const copyCode = () => {
    navigator.clipboard.writeText(sessionCode);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  // Leave session
  const leaveSession = () => {
    setCurrentView('home');
    setSessionCode('');
    setSessionData(null);
    setMessages([]);
    setInputCode('');
  };

  // Scroll to bottom
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  // Poll for new messages
  useEffect(() => {
    if (currentView === 'session' && sessionCode) {
      const interval = setInterval(async () => {
        const session = await loadSession(sessionCode);
        if (session && session.messages) {
          setMessages(session.messages);
        }
      }, 2000);

      return () => clearInterval(interval);
    }
  }, [currentView, sessionCode]);

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Format timestamp
  const formatTime = (timestamp) => {
    const date = new Date(timestamp);
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  // HOME VIEW
  if (currentView === 'home') {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 p-4">
        <div className="max-w-md mx-auto pt-20">
          <div className="bg-white rounded-3xl shadow-2xl p-8">
            <div className="text-center mb-8">
              <div className="w-20 h-20 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-full mx-auto mb-4 flex items-center justify-center">
                <Users className="w-10 h-10 text-white" />
              </div>
              <h1 className="text-3xl font-bold text-gray-800 mb-2">Study Together</h1>
              <p className="text-gray-600">Collaborate with AI assistance</p>
            </div>

            <div className="mb-6">
              <label className="block text-sm font-medium text-gray-700 mb-2">Your Name</label>
              <input
                type="text"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                placeholder="Enter your name"
                className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              />
            </div>

            <button
              onClick={createSession}
              className="w-full bg-gradient-to-r from-blue-500 to-indigo-600 text-white py-4 rounded-xl font-semibold mb-4 hover:shadow-lg transition-all"
            >
              Create New Session
            </button>

            <div className="text-center text-gray-500 mb-4">or</div>

            <button
              onClick={() => setCurrentView('join')}
              className="w-full bg-white border-2 border-blue-500 text-blue-600 py-4 rounded-xl font-semibold hover:bg-blue-50 transition-all"
            >
              Join Existing Session
            </button>
          </div>
        </div>
      </div>
    );
  }

  // JOIN VIEW
  if (currentView === 'join') {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 p-4">
        <div className="max-w-md mx-auto pt-20">
          <div className="bg-white rounded-3xl shadow-2xl p-8">
            <button
              onClick={() => setCurrentView('home')}
              className="mb-6 text-blue-600 hover:text-blue-700 flex items-center"
            >
              ← Back
            </button>

            <div className="text-center mb-8">
              <h2 className="text-2xl font-bold text-gray-800 mb-2">Join Session</h2>
              <p className="text-gray-600">Enter the code shared by your friend</p>
            </div>

            <div className="mb-6">
              <label className="block text-sm font-medium text-gray-700 mb-2">Your Name</label>
              <input
                type="text"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                placeholder="Enter your name"
                className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent mb-4"
              />

              <label className="block text-sm font-medium text-gray-700 mb-2">Session Code</label>
              <input
                type="text"
                value={inputCode}
                onChange={(e) => setInputCode(e.target.value.toUpperCase())}
                placeholder="Enter 6-character code"
                maxLength={6}
                className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent uppercase text-center text-2xl tracking-wider font-bold"
              />
            </div>

            <button
              onClick={joinSession}
              className="w-full bg-gradient-to-r from-blue-500 to-indigo-600 text-white py-4 rounded-xl font-semibold hover:shadow-lg transition-all"
            >
              Join Session
            </button>
          </div>
        </div>
      </div>
    );
  }

  // SESSION VIEW
  return (
    <div className="h-screen bg-gray-100 flex flex-col">
      {/* Header */}
      <div className="bg-gradient-to-r from-blue-500 to-indigo-600 text-white p-4 shadow-lg">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
          <div>
            <h2 className="text-xl font-bold">Study Session</h2>
            <p className="text-sm text-blue-100">
              {sessionData?.participants.filter(p => p !== username).join(', ') || 'Waiting for partner...'}
            </p>
          </div>
          <div className="flex items-center gap-3">
            <div className="bg-white/20 px-4 py-2 rounded-lg flex items-center gap-2">
              <span className="font-mono font-bold text-lg">{sessionCode}</span>
              <button onClick={copyCode} className="hover:scale-110 transition-transform">
                {copied ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
              </button>
            </div>
            <button
              onClick={leaveSession}
              className="bg-red-500 hover:bg-red-600 px-4 py-2 rounded-lg flex items-center gap-2 transition-colors"
            >
              <X className="w-4 h-4" />
              Leave
            </button>
          </div>
        </div>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 max-w-4xl mx-auto w-full">
        {messages.length === 0 && (
          <div className="text-center text-gray-500 mt-20">
            <MessageCircle className="w-16 h-16 mx-auto mb-4 text-gray-300" />
            <p>No messages yet. Start the conversation!</p>
          </div>
        )}

        {messages.map((msg) => (
          <div
            key={msg.id}
            className={`mb-4 flex ${msg.sender === username ? 'justify-end' : 'justify-start'}`}
          >
            <div className={`max-w-xs lg:max-w-md ${msg.type === 'ai' ? 'w-full max-w-2xl' : ''}`}>
              <div className="text-xs text-gray-500 mb-1 px-2">
                {msg.sender} • {formatTime(msg.timestamp)}
              </div>
              <div
                className={`rounded-2xl p-4 ${
                  msg.type === 'ai'
                    ? 'bg-gradient-to-r from-purple-100 to-pink-100 border-2 border-purple-300'
                    : msg.sender === username
                    ? 'bg-blue-500 text-white'
                    : 'bg-white text-gray-800 shadow'
                }`}
              >
                {msg.type === 'ai' && (
                  <div className="flex items-center gap-2 mb-2 text-purple-700 font-semibold">
                    <Sparkles className="w-5 h-5" />
                    AI Assistant
                  </div>
                )}
                {msg.type === 'image' ? (
                  <img src={msg.image} alt="Shared" className="rounded-lg max-w-full" />
                ) : (
                  <p className="whitespace-pre-wrap">{msg.text}</p>
                )}
              </div>
            </div>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="bg-white border-t p-4 shadow-lg">
        <div className="max-w-4xl mx-auto">
          <div className="flex items-center gap-3 mb-3">
            <button
              onClick={askAI}
              disabled={isAIThinking}
              className="bg-gradient-to-r from-purple-500 to-pink-500 text-white px-6 py-3 rounded-xl flex items-center gap-2 hover:shadow-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed font-semibold"
            >
              <Bot className="w-5 h-5" />
              {isAIThinking ? 'AI Thinking...' : 'Ask AI'}
            </button>

            <input
              type="file"
              ref={fileInputRef}
              onChange={handleImageUpload}
              accept="image/*"
              className="hidden"
            />
            <button
              onClick={() => fileInputRef.current?.click()}
              className="bg-gray-200 hover:bg-gray-300 p-3 rounded-xl transition-colors"
            >
              <Upload className="w-5 h-5 text-gray-700" />
            </button>
          </div>

          <div className="flex items-center gap-3">
            <input
              type="text"
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && sendMessage()}
              placeholder="Type your message..."
              className="flex-1 px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            />
            <button
              onClick={sendMessage}
              className="bg-blue-500 hover:bg-blue-600 text-white p-3 rounded-xl transition-colors"
            >
              <Send className="w-5 h-5" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

