    checkSubscriptionStatus();
  }, []);

  // Check subscription status every minute
  useEffect(() => {
    const interval = setInterval(() => {
      checkSubscriptionStatus();
    }, 60000); // Check every minute

    return () => clearInterval(interval);
  }, [subscriptionData]);

  // Load subscription from storage
  const loadSubscriptionData = async () => {
    try {
      const result = await window.storage.get('user_subscription', false);
      if (result) {
        const data = JSON.parse(result.value);
        setSubscriptionData(data);
        checkForNotifications(data);
      }
    } catch (error) {
      console.log('No subscription found');
    }
  };

  // Save subscription to storage
  const saveSubscriptionData = async (data) => {
    try {
      await window.storage.set('user_subscription', JSON.stringify(data), false);
      setSubscriptionData(data);
    } catch (error) {
      console.error('Failed to save subscription:', error);
    }
  };

  // Check subscription status and create notifications
  const checkSubscriptionStatus = async () => {
    if (!subscriptionData) return;

    const now = Date.now();
    const expiryDate = subscriptionData.expiryDate;
    const daysUntilExpiry = Math.ceil((expiryDate - now) / (1000 * 60 * 60 * 24));

    const newNotifications = [];

    // Critical: Expired
    if (daysUntilExpiry < 0) {
      newNotifications.push({
        id: 'expired',
        type: 'critical',
        title: 'Subscription Expired',
        message: 'Your premium subscription has expired. Renew now to continue enjoying premium features.',
        daysLeft: 0
      });
    }
    // Urgent: 1-3 days left
    else if (daysUntilExpiry <= 3) {
      newNotifications.push({
        id: 'urgent',
        type: 'urgent',
        title: 'Subscription Expiring Soon!',
        message: `Only ${daysUntilExpiry} day${daysUntilExpiry !== 1 ? 's' : ''} left! Renew now to avoid interruption.`,
        daysLeft: daysUntilExpiry
      });
    }
    // Warning: 7 days left
    else if (daysUntilExpiry <= 7) {
      newNotifications.push({
        id: 'warning',
        type: 'warning',
        title: 'Subscription Ending Soon',
        message: `Your subscription expires in ${daysUntilExpiry} days. Consider renewing early.`,
        daysLeft: daysUntilExpiry
      });
    }
