      expiryDate = now + (365 * 24 * 60 * 60 * 1000); // 365 days
      price = 99.99;
    }

    const subscriptionInfo = {
      planType,
      startDate: now,
      expiryDate,
      price,
      isActive: true,
      autoRenew: true,
      lastRenewalCheck: now
    };

    await saveSubscriptionData(subscriptionInfo);
    checkForNotifications(subscriptionInfo);
    alert(`Successfully subscribed to ${planType} plan!`);
    setCurrentView('dashboard');
  };

  // Check for notifications
  const checkForNotifications = (data) => {
    if (!data) return;

    const now = Date.now();
    const daysUntilExpiry = Math.ceil((data.expiryDate - now) / (1000 * 60 * 60 * 24));

    const newNotifications = [];

    if (daysUntilExpiry < 0) {
      newNotifications.push({
        id: 'expired',
