        console.error("Error fetching history:", error);
      });

    return () => unsubscribeHistory();
  }, [userDetails?.name]);

  // Handle active session persistence
  useEffect(() => {
    if (activeCode) {
      setSessionCode(activeCode);
      setIsSidebarOpen(false); // On mobile, close sidebar when opening a chat
    }
  }, [activeCode]);

  // --- Session Management Logic ---

  const generateCode = () => {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    let code = '';
    for (let i = 0; i < 6; i++) {
      code += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return code;
  };

  const createSession = async () => {
    if (!userDetails?.name) {
      addToast('Please ensure your profile name is set.', 'error');
      return;
    }

    const code = generateCode();
    const participant: Participant = {
        name: userDetails.name,
        photo: userDetails.profilePicture || null
    };

    const newSession: SessionData = {
      code,
      creator: userDetails.name,
      participants: [participant],
      participantNames: [userDetails.name],
      messages: [],
      createdAt: Date.now(),
      lastActivity: Date.now()
    };

    try {
        await db.collection('sessions').doc(code).set(newSession);
        handleSelectSession(code);
        addToast('New session created!', 'success');
    } catch (error) {
        console.error("Error creating session:", error);
        addToast("Failed to create session.", 'error');
    }
  };

  const joinSession = async () => {
    if (!userDetails?.name) return;
    if (!inputCode.trim()) {
      addToast('Please enter session code', 'warning');
      return;
    }

    const code = inputCode.toUpperCase();
    const sessionRef = db.collection('sessions').doc(code);

    try {
        const doc = await sessionRef.get();
        if (!doc.exists) {
            addToast('Session not found. Please check the code.', 'error');
            return;
        }

        const session = doc.data() as SessionData;

        // Add participant if not already in session
        if (!session.participantNames?.includes(userDetails.name)) {
            const newParticipant: Participant = {
                name: userDetails.name,
                photo: userDetails.profilePicture || null
            };

            await sessionRef.update({
                participants: firebase.firestore.FieldValue.arrayUnion(newParticipant),
                participantNames: firebase.firestore.FieldValue.arrayUnion(userDetails.name),
                lastActivity: Date.now()
            });
        }

        setShowJoinModal(false);
        setInputCode('');
        handleSelectSession(code);
    } catch (error) {
        console.error("Error joining session:", error);
        addToast("Failed to join session.", 'error');
    }
  };

  const handleSelectSession = (code: string) => {
      setSessionCode(code);
      setActiveCode(code);
      setIsSidebarOpen(false); // Close list on mobile
  };

  // --- Messaging Logic ---

  const sendMessage = async () => {
    if (!newMessage.trim() || !sessionCode || !userDetails) return;

    const message: Message = {
      id: Date.now().toString(),
      sender: userDetails.name,
      senderProfilePicture: userDetails.profilePicture || null,
      text: newMessage,
      timestamp: Date.now(),
      type: 'text',
      image: null,
      fileData: null,
      fileName: null,
      fileType: null
    };

    try {
        await db.collection('sessions').doc(sessionCode).update({
            messages: firebase.firestore.FieldValue.arrayUnion(message),
            lastMessage: message,
            lastActivity: Date.now()
        });
        setNewMessage('');
    } catch (error) {
        console.error("Error sending message:", error);
        addToast("Failed to send message.", 'error');
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !sessionCode || !userDetails) return;

    if (file.size > 50 * 1024 * 1024) { 
        addToast("File too large. Max size is 50MB.", 'error');
        if (e.target) e.target.value = '';
        return;
    }

    setIsUploading(true);

    try {
        const storageRef = storage.ref();
        const fileRef = storageRef.child(`sessions/${sessionCode}/${Date.now()}_${file.name}`);
        await fileRef.put(file);
        const downloadURL = await fileRef.getDownloadURL();

        const isImage = file.type.startsWith('image/');
        const message: Message = {
            id: Date.now().toString(),
            sender: userDetails.name,
            senderProfilePicture: userDetails.profilePicture || null,
            text: isImage ? '📷 Photo' : '📄 Document',
            image: isImage ? downloadURL : null,
            fileData: !isImage ? downloadURL : null,
            fileName: file.name || 'unknown',
            fileType: file.type || 'application/octet-stream',
            timestamp: Date.now(),
            type: isImage ? 'image' : 'file'
        };

        await db.collection('sessions').doc(sessionCode).update({
            messages: firebase.firestore.FieldValue.arrayUnion(message),
            lastMessage: message,
            lastActivity: Date.now()
        });

    } catch (error: any) {
        console.error("Error uploading file:", error);
        addToast("Failed to upload file.", 'error');
    } finally {
        setIsUploading(false);
        if (e.target) e.target.value = '';
    }
  };

  const askAI = async () => {
    if (messages.length === 0) {
      addToast('Start a conversation first!', 'info');
      return;
    }

    setIsAIThinking(true);
    const conversationContext = messages
      .slice(-20) // Last 20 messages for context
      .map(m => `${m.sender}: ${m.text}`)
      .join('\n');

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY! });
      const prompt = `You are an AI study assistant named Blay. 
      Conversation:\n${conversationContext}\n
      Provide a helpful, concise response to the group.`;

      const response = await ai.models.generateContent({
          model: 'gemini-2.5-flash',
          contents: prompt
      });

      const aiMessage: Message = {
        id: Date.now().toString(),
        sender: 'EduBlay AI',
        text: response.text,
        timestamp: Date.now(),
        type: 'ai',
        image: null,
        fileData: null,
        fileName: null,
        fileType: null
      };

      await db.collection('sessions').doc(sessionCode).update({
          messages: firebase.firestore.FieldValue.arrayUnion(aiMessage),
          lastMessage: aiMessage,
          lastActivity: Date.now()
      });

    } catch (error) {
      addToast('Failed to get AI response.', 'error');
    } finally {
      setIsAIThinking(false);
    }
  };

  // --- Navigation & Cleanup ---

  const handleLeaveRequest = () => setShowLeaveConfirm(true);

  const handleConfirmLeave = async () => {
    setShowLeaveConfirm(false);
    if (unsubscribeRef.current) unsubscribeRef.current();

    if (sessionCode && userDetails) {
         try {
            const participantToRemove: Participant = {
                name: userDetails.name,
                photo: userDetails.profilePicture || null
            };
            await db.collection('sessions').doc(sessionCode).update({
                participants: firebase.firestore.FieldValue.arrayRemove(participantToRemove),
                participantNames: firebase.firestore.FieldValue.arrayRemove(userDetails.name)
            });
        } catch (e) { console.warn(e); }
    }

    setActiveCode(null);
    setSessionCode('');
    setSessionData(null);
    setMessages([]);
    setIsSidebarOpen(true);
  };

  // Real-time listener for active session
  useEffect(() => {
    if (sessionCode) {
      const unsubscribe = db.collection('sessions').doc(sessionCode)
        .onSnapshot((doc) => {
            if (doc.exists) {
                const data = doc.data() as SessionData;
                setSessionData(data);
                setMessages(data.messages || []);
            } else {
                addToast("Session ended.", 'info');
                setActiveCode(null);
                setSessionCode('');
                setIsSidebarOpen(true);
            }
        });
      unsubscribeRef.current = unsubscribe;
      return () => unsubscribe();
    }
  }, [sessionCode, setActiveCode]); 

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // --- Helpers ---

  const copyCode = () => {
    navigator.clipboard.writeText(sessionCode);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const formatTime = (timestamp: number) => {
    return new Date(timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  const getInitials = (name: string) => name ? name.charAt(0).toUpperCase() : '?';

  // Filter history based on search
  const filteredHistory = useMemo(() => {
      return sessionHistory.filter(session => {
          const names = session.participants.map(p => p.name).join(' ').toLowerCase();
          const code = session.code.toLowerCase();
          const query = searchQuery.toLowerCase();
          return names.includes(query) || code.includes(query);
      });
  }, [sessionHistory, searchQuery]);

  const getOtherParticipant = (session: SessionData) => {
      if (!userDetails) return null;
      // If more than 2 people (including me), it's a group
      if (session.participants.length > 2) return null; 
      // Find the one that isn't me
      return session.participants.find(p => p.name !== userDetails.name);
  };

  return (
    <div className="h-[calc(100vh-90px)] flex bg-white dark:bg-gray-900 rounded-2xl shadow-xl overflow-hidden border dark:border-gray-700 -mx-4 sm:mx-0">

      {/* --- LEFT SIDEBAR (History List) --- */}
      <div className={`w-full md:w-80 flex-shrink-0 flex flex-col bg-white dark:bg-gray-800 border-r dark:border-gray-700 ${!isSidebarOpen && sessionCode ? 'hidden md:flex' : 'flex'}`}>
        {/* Sidebar Header */}
        <div className="p-4 bg-gray-50 dark:bg-gray-800/50 border-b dark:border-gray-700 flex justify-between items-center">
            <div className="flex items-center gap-2">
                 {userDetails?.profilePicture ? (
                    <img src={userDetails.profilePicture} alt="Me" className="w-10 h-10 rounded-full object-cover" />
                ) : (
                    <div className="w-10 h-10 bg-blue-100 dark:bg-blue-900 text-blue-600 rounded-full flex items-center justify-center font-bold">
                        {getInitials(userDetails?.name || '')}
                    </div>
                )}
                <span className="font-bold text-gray-800 dark:text-white truncate max-w-[120px]">{userDetails?.name}</span>
            </div>
            <div className="flex gap-2">
                <button onClick={() => setShowJoinModal(true)} title="Join Session" className="p-2 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full">
                    <Users className="w-5 h-5" />
                </button>
                <button onClick={() => onActionAttempt(createSession)} title="New Chat" className="p-2 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full">
                    <MessageCircle className="w-5 h-5" />
                </button>
            </div>
        </div>

        {/* Search Bar */}
        <div className="p-3">
            <div className="relative">
                <input 
                    type="text" 
                    placeholder="Search conversations..." 
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="w-full pl-10 pr-4 py-2 bg-gray-100 dark:bg-gray-700 border-none rounded-lg text-sm focus:ring-2 focus:ring-blue-500 text-gray-900 dark:text-white placeholder-gray-500"
                />
                <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
            </div>
        </div>

        {/* Chats List */}
        <div className="flex-1 overflow-y-auto">
            {filteredHistory.length === 0 ? (
                <div className="p-8 text-center text-gray-500 dark:text-gray-400">
                    <p className="text-sm">No conversations yet.</p>
                    <p className="text-xs mt-2">Start a new session to chat!</p>
                </div>
            ) : (
                filteredHistory.map((session) => {
                    const other = getOtherParticipant(session);
                    const isGroup = !other;
                    const isActive = session.code === sessionCode;
                    const lastMsg = session.lastMessage;

                    return (
                        <div 
                            key={session.code}
                            onClick={() => handleSelectSession(session.code)}
                            className={`flex items-center gap-3 p-3 cursor-pointer transition-colors border-b dark:border-gray-700/50 hover:bg-gray-50 dark:hover:bg-gray-700 ${isActive ? 'bg-blue-50 dark:bg-blue-900/20' : ''}`}
                        >
                            <div className="relative flex-shrink-0">
                                {isGroup ? (
                                    <div className="w-12 h-12 bg-indigo-100 dark:bg-indigo-900 text-indigo-600 rounded-full flex items-center justify-center">
                                        <Users className="w-6 h-6" />
                                    </div>
                                ) : (
                                    other?.photo ? (
                                        <img src={other.photo} alt={other.name} className="w-12 h-12 rounded-full object-cover" />
                                    ) : (
                                        <div className="w-12 h-12 bg-purple-100 dark:bg-purple-900 text-purple-600 rounded-full flex items-center justify-center font-bold text-lg">
                                            {getInitials(other?.name || '?')}
                                        </div>
                                    )
                                )}
                            </div>
                            <div className="flex-1 min-w-0">
                                <div className="flex justify-between items-baseline">
                                    <h4 className="font-semibold text-gray-900 dark:text-gray-100 truncate">
                                        {isGroup ? `Group (${session.participants.length})` : other?.name}
                                    </h4>
                                    {session.lastActivity && (
                                        <span className="text-[10px] text-gray-500">{new Date(session.lastActivity).toLocaleDateString(undefined, {month: 'short', day: 'numeric'})}</span>
                                    )}
                                </div>
                                <div className="flex justify-between items-center">
                                    <p className="text-sm text-gray-500 dark:text-gray-400 truncate">
                                        {lastMsg ? (
                                            <span className="flex items-center gap-1">
                                                {lastMsg.sender === userDetails?.name && <span className="text-blue-500">✓</span>}
                                                {lastMsg.type === 'image' ? '📷 Photo' : lastMsg.type === 'file' ? '📄 File' : lastMsg.text}
                                            </span>
                                        ) : (
                                            <span className="italic">No messages</span>
                                        )}
                                    </p>
                                    {/* Could add unread count here later */}
                                </div>
                            </div>
                        </div>
                    );
                })
            )}
        </div>
      </div>

      {/* --- RIGHT AREA (Chat Interface) --- */}
      <div className={`flex-1 flex flex-col bg-[#e5ded8] dark:bg-[#0b141a] ${isSidebarOpen && !activeCode ? 'hidden md:flex' : 'flex'}`}>
        {sessionCode ? (
            <>
                {/* Active Chat Header */}
                <div className="p-3 bg-white dark:bg-gray-800 border-b dark:border-gray-700 flex items-center justify-between shadow-sm">
                    <div className="flex items-center gap-3">
                        <button onClick={() => setIsSidebarOpen(true)} className="md:hidden p-2 -ml-2 text-gray-600 dark:text-gray-300">
                            <ArrowLeft className="w-5 h-5" />
                        </button>
                        <div className="flex items-center gap-3" onClick={copyCode} title="Click to copy code">
                             {/* Avatar Logic for Header */}
                             {(() => {
                                 const other = sessionData ? getOtherParticipant(sessionData) : null;
                                 const isGroup = !other;

                                 if(isGroup) return (
                                     <div className="w-10 h-10 bg-indigo-100 dark:bg-indigo-900 text-indigo-600 rounded-full flex items-center justify-center">
                                        <Users className="w-5 h-5" />
                                     </div>
                                 );
                                 if(other?.photo) return <img src={other.photo} className="w-10 h-10 rounded-full object-cover" alt={other.name} />;
                                 return (
                                    <div className="w-10 h-10 bg-purple-100 dark:bg-purple-900 text-purple-600 rounded-full flex items-center justify-center font-bold">
                                        {getInitials(other?.name || '?')}
                                    </div>
                                 );
                             })()}

                             <div>
                                 <h2 className="font-bold text-gray-900 dark:text-white flex items-center gap-2">
                                     {sessionData && (getOtherParticipant(sessionData)?.name || "Group Study")}
                                     <span className="text-xs font-normal px-2 py-0.5 bg-gray-200 dark:bg-gray-700 rounded-full text-gray-600 dark:text-gray-300 select-all">
                                         {sessionCode}
                                     </span>
                                 </h2>
                                 <p className="text-xs text-gray-500 dark:text-gray-400">
                                     {sessionData?.participants.map(p => p.name).join(', ')}
                                 </p>
                             </div>
                        </div>
                    </div>
                    <div className="flex items-center gap-2">
                        <button onClick={askAI} disabled={isAIThinking} className="p-2 text-purple-600 hover:bg-purple-50 dark:hover:bg-gray-700 rounded-full" title="Ask AI">
                            <Sparkles className={`w-5 h-5 ${isAIThinking ? 'animate-spin' : ''}`} />
                        </button>
                        <button onClick={handleLeaveRequest} className="p-2 text-red-500 hover:bg-red-50 dark:hover:bg-gray-700 rounded-full" title="Leave Session">
                            <LogOut className="w-5 h-5" />
                        </button>
                    </div>
                </div>

                {/* Messages Area */}
                <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-[url('https://user-images.githubusercontent.com/15075759/28719144-86dc0f70-73b1-11e7-911d-60d70fcded21.png')] dark:bg-[url('https://user-images.githubusercontent.com/15075759/28719144-86dc0f70-73b1-11e7-911d-60d70fcded21.png')] bg-repeat">
                    {messages.map((msg) => {
                        const isMe = msg.sender === userDetails?.name;
                        const isAI = msg.type === 'ai';

                        return (
                            <div key={msg.id} className={`flex ${isMe ? 'justify-end' : 'justify-start'} ${isAI ? 'justify-center' : ''}`}>
                                {isAI ? (
                                     <div className="bg-white/90 dark:bg-gray-800/90 backdrop-blur-sm p-4 rounded-xl shadow-sm max-w-lg border-t-4 border-purple-500 text-sm">
                                         <div className="flex items-center gap-2 mb-1 font-bold text-purple-600">
                                             <Bot className="w-4 h-4" /> EduBlay AI
                                         </div>
                                         <p className="text-gray-800 dark:text-gray-200 whitespace-pre-wrap">{msg.text}</p>
                                     </div>
                                ) : (
                                    <div className={`flex max-w-[80%] sm:max-w-[60%] ${isMe ? 'flex-row-reverse' : 'flex-row'}`}>
                                        {/* Message Bubble */}
                                        <div className={`relative p-2 rounded-lg shadow-sm text-sm ${
                                            isMe 
                                            ? 'bg-[#d9fdd3] dark:bg-[#005c4b] text-gray-900 dark:text-gray-100 rounded-tr-none' 
                                            : 'bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100 rounded-tl-none'
                                        }`}>
                                            {!isMe && <p className="text-xs font-bold text-orange-600 mb-1">{msg.sender}</p>}

                                            {msg.type === 'image' && (
                                                <img src={msg.image || ''} alt="Shared" className="rounded-md max-w-full max-h-60 object-cover mb-1" />
                                            )}

                                            {msg.type === 'file' && (
                                                 <div className="flex items-center gap-3 p-2 bg-black/5 dark:bg-white/10 rounded-md mb-1">
                                                    <FileText className="w-8 h-8 text-blue-500" />
                                                    <div className="flex-1 min-w-0 overflow-hidden">
                                                        <p className="truncate font-medium">{msg.fileName}</p>
                                                        <p className="text-xs opacity-70 uppercase">{msg.fileType?.split('/')[1]}</p>
                                                    </div>
                                                    <a href={msg.fileData || '#'} download={msg.fileName} target="_blank" rel="noreferrer" className="p-1.5 bg-white dark:bg-gray-700 rounded-full shadow-sm">
                                                        <Download className="w-4 h-4" />
                                                    </a>
                                                 </div>
                                            )}

                                            {msg.text && <p className="whitespace-pre-wrap leading-relaxed">{msg.text}</p>}

                                            <div className={`text-[10px] mt-1 text-right ${isMe ? 'text-gray-500 dark:text-gray-300' : 'text-gray-500'}`}>
                                                {formatTime(msg.timestamp)}
                                                {isMe && <span className="ml-1 text-blue-500">✓</span>}
                                            </div>
                                        </div>
                                    </div>
                                )}
                            </div>
                        );
                    })}
                    <div ref={messagesEndRef} />
                </div>

                {/* Input Area */}
                <div className="p-3 bg-gray-100 dark:bg-gray-800 flex items-center gap-2">
                    <button onClick={() => fileInputRef.current?.click()} className="p-2 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200" disabled={isUploading}>
                         {isUploading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Upload className="w-6 h-6" />}
                    </button>
                    <input
                        type="file"
                        ref={fileInputRef}
                        onChange={handleFileUpload}
                        className="hidden"
                        accept="image/*,application/pdf,application/vnd.ms-powerpoint,application/vnd.openxmlformats-officedocument.presentationml.presentation"
                    />
                    <div className="flex-1 bg-white dark:bg-gray-700 rounded-full px-4 py-2 flex items-center">
                        <input
                            type="text"
                            value={newMessage}
                            onChange={(e) => setNewMessage(e.target.value)}
                            onKeyPress={(e) => e.key === 'Enter' && sendMessage()}
                            placeholder="Type a message"
                            className="flex-1 bg-transparent border-none focus:ring-0 text-gray-900 dark:text-white placeholder-gray-500"
                        />
                    </div>
                    <button 
                        onClick={sendMessage} 
                        disabled={!newMessage.trim()} 
                        className="p-2 bg-green-600 text-white rounded-full hover:bg-green-700 disabled:opacity-50 disabled:bg-gray-400 shadow-sm"
                    >
                        <Send className="w-5 h-5" />
                    </button>
                </div>
            </>
        ) : (
            /* Empty State (Desktop) */
            <div className="flex-1 flex flex-col items-center justify-center bg-gray-100 dark:bg-gray-900 text-center p-8 border-b-8 border-green-500">
                <div className="w-40 h-40 bg-white dark:bg-gray-800 rounded-full flex items-center justify-center shadow-xl mb-6">
                    <img src="https://upload.wikimedia.org/wikipedia/commons/thumb/6/6b/WhatsApp.svg/1200px-WhatsApp.svg.png" alt="Connect" className="w-24 h-24 opacity-80 grayscale" style={{ filter: 'grayscale(100%) opacity(0.5)' }} />
                </div>
                <h1 className="text-3xl font-light text-gray-700 dark:text-gray-200 mb-4">EduBlay Connect</h1>
                <p className="text-gray-500 dark:text-gray-400 max-w-md">
                    Send and receive messages, share study materials, and collaborate with AI assistance in real-time.
                </p>
                <div className="mt-8 flex items-center gap-2 text-sm text-gray-400">
                    <LockIcon className="w-3 h-3" /> End-to-end encrypted connection
                </div>
            </div>
        )}
      </div>

      {/* Join Session Modal */}
      {showJoinModal && (
          <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4">
              <div className="bg-white dark:bg-gray-800 rounded-xl p-6 w-full max-w-sm shadow-2xl">
                  <h3 className="text-lg font-bold mb-4 dark:text-white">Join New Session</h3>
                  <input
                    type="text"
                    value={inputCode}
                    onChange={(e) => setInputCode(e.target.value.toUpperCase())}
                    placeholder="Enter 6-digit code"
                    maxLength={6}
                    className="w-full p-3 border rounded-lg mb-4 text-center font-mono text-xl tracking-widest uppercase dark:bg-gray-700 dark:border-gray-600 dark:text-white"
                  />
                  <div className="flex gap-2">
                      <button onClick={() => setShowJoinModal(false)} className="flex-1 py-2 bg-gray-200 dark:bg-gray-700 rounded-lg font-medium">Cancel</button>
                      <button onClick={joinSession} className="flex-1 py-2 bg-green-600 text-white rounded-lg font-medium hover:bg-green-700">Join</button>
                  </div>
              </div>
          </div>
      )}

      <ConfirmationModal
        isOpen={showLeaveConfirm}
        onClose={() => setShowLeaveConfirm(false)}
        onConfirm={handleConfirmLeave}
        title="Leave Chat?"
        message="You can rejoin later using the session code."
        confirmText="Leave"
        confirmColor="red"
      />
    </div>
  );
}

