import React, { useState, useEffect, useRef, useMemo } from 'react';
import { MessageCircle, Send, Bot, Upload, X, Copy, Check, Users, Sparkles, ArrowLeft, FileText, Download, Loader2, Search, MoreVertical, LogOut, Share2, Lock } from 'lucide-react';
import { TrashIcon } from './icons/TrashIcon';
import { SaveIcon } from './icons/SaveIcon';
import { PencilIcon } from './icons/PencilIcon';
import { CheckIcon } from './icons/CheckIcon';
import { CopyIcon } from './icons/CopyIcon';
import { db, storage } from '../src/services/firebase';
import firebase from 'firebase/compat/app';
import { GoogleGenAI } from "@google/genai";
import type { UserDetails, Toast, Note } from '../types';
import ConfirmationModal from './ConfirmationModal';

interface CollaborativeSessionProps {
  userDetails: UserDetails | null;
  addToast: (message: string, type: Toast['type']) => void;
  onActionAttempt: (action: () => Promise<void>) => void;
  activeCode: string | null;
  setActiveCode: (code: string | null) => void;
  notes: Note[];
  setNotes: (notes: Note[]) => void;
}

interface Message {
  id: string;
  sender: string;
  senderProfilePicture?: string | null;
  text: string;
  image?: string | null;
  fileData?: string | null;
  fileName?: string | null;
  fileType?: string | null;
  timestamp: number;
  type: 'text' | 'image' | 'ai' | 'file';
}

interface Participant {
  name: string;
  photo?: string | null;
}

interface SessionData {
  code: string;
  creator: string;
  participants: Participant[];
  participantNames: string[];
  messages: Message[];
  createdAt: number;
  lastMessage?: Message;
  lastActivity?: number;
}

export function CollaborativeSession({ userDetails, addToast, onActionAttempt, activeCode, setActiveCode, notes, setNotes }: CollaborativeSessionProps) {
  // View State
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');

  // Data State
  const [sessionHistory, setSessionHistory] = useState<SessionData[]>([]);
  const [sessionCode, setSessionCode] = useState('');
  const [sessionData, setSessionData] = useState<SessionData | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);

  // Input State
  const [inputCode, setInputCode] = useState('');
  const [newMessage, setNewMessage] = useState('');
  const [isAIThinking, setIsAIThinking] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [showLeaveConfirm, setShowLeaveConfirm] = useState(false);
  const [showJoinModal, setShowJoinModal] = useState(false);

  // Editing State
  const [editingMessageId, setEditingMessageId] = useState<string | null>(null);
  const [editMessageText, setEditMessageText] = useState('');
  const [sessionToDelete, setSessionToDelete] = useState<string | null>(null);

  // Invite & Pairing State
  const [createdSessionCode, setCreatedSessionCode] = useState<string | null>(null);
  const [showShareConfirm, setShowShareConfirm] = useState(false);

  // Strict Verification State: Initialize based on activeCode to prevent content flash
  const [isVerifyingConnection, setIsVerifyingConnection] = useState(!!activeCode);
  const [connectionSuccess, setConnectionSuccess] = useState(false);

  // Refs
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const unsubscribeRef = useRef<(() => void) | null>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  // --- Initialization & History Fetching ---

  useEffect(() => {
    if (!userDetails?.name) return;

    const unsubscribeHistory = db.collection('sessions')
      .where('participantNames', 'array-contains', userDetails.name)
      .onSnapshot((snapshot) => {
        const history = snapshot.docs.map(doc => ({ ...doc.data(), code: doc.id } as SessionData));
        history.sort((a, b) => (b.lastActivity || 0) - (a.lastActivity || 0));
        setSessionHistory(history);
      }, (error) => {
        console.error("Error fetching history:", error);
      });

    return () => unsubscribeHistory();
  }, [userDetails?.name]);

  useEffect(() => {
    if (activeCode) {
      setSessionCode(activeCode);
      setIsSidebarOpen(false);
      // When navigating back to the session, immediately enforce verification state
      // until the live data snapshot confirms the partner is present.
      setIsVerifyingConnection(true);
    }
  }, [activeCode]);

  // --- Session Management Logic ---

  const generateCode = () => {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    let code = '';
    for (let i = 0; i < 6; i++) {
      code += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return code;
  };

  const createSession = async () => {
    if (!userDetails?.name) {
      addToast('Please ensure your profile name is set.', 'error');
      return;
    }

    const code = generateCode();
    const participant: Participant = {
        name: userDetails.name,
        photo: userDetails.profilePicture || null
    };

    const newSession: SessionData = {
      code,
      creator: userDetails.name,
      participants: [participant],
      participantNames: [userDetails.name],
      messages: [],
      createdAt: Date.now(),
      lastActivity: Date.now()
    };

    try {
        await db.collection('sessions').doc(code).set(newSession);
        handleSelectSession(code);
        setCreatedSessionCode(code); // Trigger the Invite Modal

        // Start in waiting state
        setIsVerifyingConnection(true); 
        setConnectionSuccess(false);
    } catch (error) {
        console.error("Error creating session:", error);
        addToast("Failed to create session. Check your connection.", 'error');
    }
  };

  const joinSession = async () => {
    if (!userDetails?.name) return;
    if (!inputCode.trim()) {
      addToast('Please enter session code', 'warning');
      return;
    }

    if (!navigator.onLine) {
      addToast('You are offline. Please connect to the internet to join a session.', 'error');
      return;
    }

    const code = inputCode.toUpperCase();
    const sessionRef = db.collection('sessions').doc(code);

    try {
        const doc = await sessionRef.get();

        if (!doc.exists) {
            addToast('Session not found. Please check the code.', 'error');
            return;
        }

        const session = doc.data() as SessionData;

        if (!session.participantNames?.includes(userDetails.name)) {
            const newParticipant: Participant = {
                name: userDetails.name,
                photo: userDetails.profilePicture || null
            };

            await sessionRef.update({
                participants: firebase.firestore.FieldValue.arrayUnion(newParticipant),
                participantNames: firebase.firestore.FieldValue.arrayUnion(userDetails.name),
                lastActivity: Date.now()
            });
        }

        setShowJoinModal(false);
        setInputCode('');
        handleSelectSession(code);
        addToast("Successfully paired!", 'success');
    } catch (error: any) {
        console.error("Error joining session:", error);
        if (error.message && error.message.includes('offline')) {
             addToast("Could not connect to server. Please check your internet.", 'error');
        } else {
             addToast("Failed to join session. Please try again.", 'error');
        }
    }
  };

  const handleSelectSession = (code: string) => {
      setSessionCode(code);
      setActiveCode(code);
      setIsSidebarOpen(false);

      // Always start in verification mode when selecting a session.
      // The onSnapshot listener will unlock it if a partner is present.
      setIsVerifyingConnection(true); 
      setConnectionSuccess(false);
  };

  // --- Share Logic ---
  const shareCode = async (codeOverride?: string) => {
      const explicitCode = typeof codeOverride === 'string' ? codeOverride : undefined;
      const codeToShare = explicitCode || createdSessionCode || sessionCode;

      if (!codeToShare) {
          addToast("No code available to share.", 'error');
          return;
      }

      const shareData: ShareData = {
          title: 'Join my Study Session on EduBlay',
          text: `Let's pair up on EduBlay Study Hub! My Pairing Code is: ${codeToShare}`,
      };

      if (window.location.protocol.startsWith('http')) {
          shareData.url = window.location.href;
      }

      if (navigator.share) {
          try {
              if (navigator.canShare && !navigator.canShare(shareData)) {
                  delete shareData.url; 
              }
              await navigator.share(shareData);
          } catch (err: any) {
              if (err.name !== 'AbortError') {
                  console.error("Share error:", err);
                  addToast("Unable to open share menu. Please use the Copy button.", 'error');
              }
          }
      } else {
          copyCode(codeToShare);
      }
  };

  const copyCode = (codeToCopy: string = sessionCode) => {
    if (!codeToCopy) return;
    navigator.clipboard.writeText(codeToCopy)
        .then(() => addToast("Code copied to clipboard!", 'success'))
        .catch((err) => {
            console.error("Copy error:", err);
            addToast("Failed to copy code.", 'error');
        });
  };

  const handleStartChattingClick = () => {
      setShowShareConfirm(true);
  };

  const confirmShared = () => {
      setShowShareConfirm(false);
      setCreatedSessionCode(null);
      // Do NOT manually set isVerifyingConnection here.
      // It remains true from createSession/handleSelectSession until the snapshot confirms a partner.
  };

  // --- Messaging Logic ---

  const sendMessage = async () => {
    if (!newMessage.trim() || !sessionCode || !userDetails) return;

    const message: Message = {
      id: Date.now().toString(),
      sender: userDetails.name,
      senderProfilePicture: userDetails.profilePicture || null,
      text: newMessage,
      timestamp: Date.now(),
      type: 'text',
      image: null,
      fileData: null,
      fileName: null,
      fileType: null
    };

    try {
        await db.collection('sessions').doc(sessionCode).update({
            messages: firebase.firestore.FieldValue.arrayUnion(message),
            lastMessage: message,
            lastActivity: Date.now()
        });
        setNewMessage('');
    } catch (error) {
        console.error("Error sending message:", error);
        addToast("Failed to send message.", 'error');
    }
  };

  const handleEditMessage = async (messageId: string, newText: string) => {
      if (!sessionCode) return;
      try {
          const docRef = db.collection('sessions').doc(sessionCode);
          const doc = await docRef.get();
          if (doc.exists) {
              const data = doc.data() as SessionData;
              const updatedMessages = data.messages.map(m => m.id === messageId ? { ...m, text: newText } : m);
              await docRef.update({ messages: updatedMessages });
              setEditingMessageId(null);
              setEditMessageText('');
          }
      } catch (error) { console.error(error); addToast("Failed to edit message.", 'error'); }
  };

  const handleDeleteSession = async (codeToDelete: string) => {
      if (!userDetails) return;
      try {
        setSessionHistory(prev => prev.filter(s => s.code !== codeToDelete));
        if (sessionCode === codeToDelete) {
            setActiveCode(null);
            setSessionCode('');
            setSessionData(null);
            setMessages([]);
            setIsSidebarOpen(true);
        }
        const sessionRef = db.collection('sessions').doc(codeToDelete);
        const doc = await sessionRef.get();
        if (doc.exists) {
            const data = doc.data() as SessionData;
            const participantToRemove = data.participants.find(p => p.name === userDetails.name);
            if (participantToRemove) {
                await sessionRef.update({
                    participants: firebase.firestore.FieldValue.arrayRemove(participantToRemove),
                    participantNames: firebase.firestore.FieldValue.arrayRemove(userDetails.name)
                });
            }
        }
        setSessionToDelete(null);
        addToast("Chat deleted.", 'success');
      } catch (error) { console.error(error); addToast("Failed to delete chat.", 'error'); }
  };

  const handleSaveToNotes = (text: string) => {
    const newNote: Note = {
        id: Date.now().toString(),
        title: `Chat from Session ${sessionCode}`,
        content: text,
        subject: 'Collaborative Session',
        createdAt: new Date().toISOString(),
        isFavourite: false,
    };
    setNotes([newNote, ...notes]);
    addToast('Message saved to notes!', 'success');
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !sessionCode || !userDetails) return;
    if (file.size > 50 * 1024 * 1024) { 
        addToast("File too large. Max size is 50MB.", 'error');
        return;
    }
    setIsUploading(true);
    try {
        const storageRef = storage.ref();
        const fileRef = storageRef.child(`sessions/${sessionCode}/${Date.now()}_${file.name}`);
        await fileRef.put(file);
        const downloadURL = await fileRef.getDownloadURL();
        const isImage = file.type.startsWith('image/');
        const message: Message = {
            id: Date.now().toString(),
            sender: userDetails.name,
            senderProfilePicture: userDetails.profilePicture || null,
            text: isImage ? '📷 Photo' : '📄 Document',
            image: isImage ? downloadURL : null,
            fileData: !isImage ? downloadURL : null,
            fileName: file.name || 'unknown',
            fileType: file.type || 'application/octet-stream',
            timestamp: Date.now(),
            type: isImage ? 'image' : 'file'
        };
        await db.collection('sessions').doc(sessionCode).update({
            messages: firebase.firestore.FieldValue.arrayUnion(message),
            lastMessage: message,
            lastActivity: Date.now()
        });
    } catch (error: any) { console.error(error); addToast("Failed to upload file.", 'error'); } 
    finally { setIsUploading(false); if (e.target) e.target.value = ''; }
  };

  const askAI = async () => {
    if (messages.length === 0) { addToast('Start a conversation first!', 'info'); return; }
    setIsAIThinking(true);
    const conversationContext = messages.slice(-20).map(m => `${m.sender}: ${m.text}`).join('\n');
    try {
