                  <input type="text" value={inputCode} onChange={(e) => setInputCode(e.target.value.toUpperCase())} placeholder="Enter 6-digit code" maxLength={6} className="w-full p-3 border rounded-lg mb-4 text-center font-mono text-xl tracking-widest uppercase dark:bg-gray-700 dark:border-gray-600 dark:text-white" />
                  <div className="flex gap-2">
                      <button onClick={() => setShowJoinModal(false)} className="flex-1 py-2 bg-gray-200 dark:bg-gray-700 rounded-lg font-medium">Cancel</button>
                      <button onClick={joinSession} className="flex-1 py-2 bg-green-600 text-white rounded-lg font-medium hover:bg-green-700">Join</button>
                  </div>
              </div>
          </div>
      )}

      <ConfirmationModal isOpen={showLeaveConfirm} onClose={() => setShowLeaveConfirm(false)} onConfirm={handleConfirmLeave} title="Leave Chat?" message="You can rejoin later using the session code." confirmText="Leave" confirmColor="red" />
      <ConfirmationModal isOpen={!!sessionToDelete} onClose={() => setSessionToDelete(null)} onConfirm={() => sessionToDelete && handleDeleteSession(sessionToDelete)} title="Delete Chat?" message="Are you sure you want to delete this chat? This will remove it from your list." confirmText="Delete" confirmColor="red" />

      <ConfirmationModal 
        isOpen={showShareConfirm} 
        onClose={() => setShowShareConfirm(false)} 
        onConfirm={confirmShared} 
        title="Did you share the code?" 
        message="The session will be locked in a 'Waiting' state until your partner enters the code you just generated." 
        confirmText="Yes, I shared it" 
        confirmColor="green" 
      />
    </div>
  );
}

