import React, { useState, useEffect, useRef, useMemo } from 'react';
import { MessageCircle, Send, Bot, Upload, X, Copy, Check, Users, Sparkles, ArrowLeft, FileText, Download, Loader2, Search, MoreVertical, LogOut, Share2, Lock, Mic, Square, Trash2 } from 'lucide-react';
