      .onSnapshot((snapshot) => {
        const history = snapshot.docs.map(doc => ({ ...doc.data(), code: doc.id } as SessionData));
        history.sort((a, b) => (b.lastActivity || 0) - (a.lastActivity || 0));
        setSessionHistory(history);
      }, (error) => {
        console.error("Error fetching history:", error);
      });

    return () => unsubscribeHistory();
  }, [userDetails?.name]);

  // Handle Returning from Navigation (Persistence)
  useEffect(() => {
    if (activeCode) {
      // User returned to the session they were already in.
      // Don't ask to pair again, just restore state.
      setSessionCode(activeCode);
      setIsSidebarOpen(false);
      setIsViewOnly(false);
      // We rely on the snapshot listener to determine if we need to verify connection,
      // but initially we assume they are connected if they have an activeCode.
      setIsVerifyingConnection(false); 
    }
  }, [activeCode]);

  // Cleanup typing status on unmount or session change
  useEffect(() => {
