nsparent border-none focus:ring-0 text-gray-900 dark:text-white placeholder-gray-500 disabled:opacity-50" /></div>{newMessage.trim() ? <button onClick={sendMessage} disabled={isVerifyingConnection || isViewOnly} className="p-2 bg-green-600 text-white rounded-full hover:bg-green-700 disabled:opacity-50 disabled:bg-gray-400 shadow-sm"><Send className="w-5 h-5" /></button> : <button onClick={startRecording} disabled={isVerifyingConnection || isViewOnly} className="p-2 bg-blue-500 text-white rounded-full hover:bg-blue-600 disabled:opacity-50 disabled:bg-gray-400 shadow-sm"><Mic className="w-5 h-5" /></button>}</>}
