      <ConfirmationModal isOpen={showShareConfirm} onClose={() => setShowShareConfirm(false)} onConfirm={confirmShared} title="Did you share the code?" message="The session will be locked in a 'Waiting' state until your partner enters the code you just generated." confirmText="Yes, I shared it" confirmColor="green" />
