  const fileInputRef = useRef<HTMLInputElement>(null);
  const unsubscribeRef = useRef<(() => void) | null>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  // --- Initialization & History Fetching ---

  useEffect(() => {
    if (!userDetails?.name) return;

    const unsubscribeHistory = db.collection('sessions')
      .where('participantNames', 'array-contains', userDetails.name)
      .onSnapshot((snapshot) => {
        const history = snapshot.docs.map(doc => ({ ...doc.data(), code: doc.id } as SessionData));
        // Sort client-side by lastActivity desc
        history.sort((a, b) => (b.lastActivity || 0) - (a.lastActivity || 0));
        setSessionHistory(history);
      }, (error) => {
        console.error("Error fetching history:", error);
      });

    return () => unsubscribeHistory();
  }, [userDetails?.name]);

  // Handle Returning from Navigation (Persistence)
  useEffect(() => {
    if (activeCode) {
      setSessionCode(activeCode);
      setIsSidebarOpen(false);
      setIsViewOnly(false);
      setIsVerifyingConnection(true);
    }
  }, [activeCode]);

  // --- HEARTBEAT SYSTEM ---
  useEffect(() => {
      if (sessionCode && userDetails && !isViewOnly) {
          const sessionRef = db.collection('sessions').doc(sessionCode);

          const sendHeartbeat = () => {
              sessionRef.update({
                  [`activeParticipants.${userDetails.name}`]: Date.now()
              }).catch(e => console.warn("Heartbeat failed", e));
          };

          sendHeartbeat();
          const heartbeatInterval = setInterval(sendHeartbeat, 10000);

          const cleanup = () => {
              if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
              clearInterval(heartbeatInterval);
              sessionRef.update({
                  [`activeParticipants.${userDetails.name}`]: firebase.firestore.FieldValue.delete(),
                  [`typing.${userDetails.name}`]: firebase.firestore.FieldValue.delete()
              }).catch(e => console.warn("Cleanup failed", e));
          };

          window.addEventListener('beforeunload', cleanup);
          return () => {
              window.removeEventListener('beforeunload', cleanup);
              cleanup();
          };
      }
  }, [sessionCode, userDetails, isViewOnly]);

  // Click outside listener for emoji picker
  useEffect(() => {
      const closePicker = (e: any) => {
          if (showEmojiPicker && !e.target.closest('.emoji-picker-container')) {
              setShowEmojiPicker(false);
          }
      }
      document.addEventListener('mousedown', closePicker);
      return () => document.removeEventListener('mousedown', closePicker);
  }, [showEmojiPicker]);

  // --- Helpers ---

  const sendSystemMessage = async (text: string, code: string = sessionCode) => {
      if (!code) return;
      const systemMsg: Message = {
          id: Date.now().toString(),
          sender: 'System',
          text: text,
          timestamp: Date.now(),
          type: 'system'
      };
      try {
          await db.collection('sessions').doc(code).update({
              messages: firebase.firestore.FieldValue.arrayUnion(systemMsg),
              lastActivity: Date.now()
          });
      } catch (e) { console.error("Failed to send system message", e); }
  };

  const updateTypingStatus = async (isTyping: boolean) => {
      if (!sessionCode || !userDetails || isViewOnly) return;
      try {
          await db.collection('sessions').doc(sessionCode).update({
              [`typing.${userDetails.name}`]: isTyping ? true : firebase.firestore.FieldValue.delete()
          });
      } catch (e) { }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      setNewMessage(e.target.value);
      if (!sessionCode || isViewOnly) return;
      updateTypingStatus(true);
      if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
      typingTimeoutRef.current = setTimeout(() => { updateTypingStatus(false); }, 2000);
  };

  const handleEmojiClick = (emoji: string) => {
      if (isViewOnly) return;
      setNewMessage(prev => prev + emoji);
      updateTypingStatus(true);
      if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
      typingTimeoutRef.current = setTimeout(() => { updateTypingStatus(false); }, 2000);
  };

  // --- Session Management Logic ---

  const generateCode = () => {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    let code = '';
    for (let i = 0; i < 6; i++) {
      code += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return code;
  };

  const createSession = async () => {
    if (!userDetails?.name) {
      addToast('Please ensure your profile name is set.', 'error');
      return;
    }

    const code = generateCode();
    const participant: Participant = {
        name: userDetails.name,
        photo: userDetails.profilePicture || null
    };

    const newSession: SessionData = {
      code,
      creator: userDetails.name,
      participants: [participant],
      participantNames: [userDetails.name],
      activeParticipants: { [userDetails.name]: Date.now() },
      messages: [],
      typing: {},
      createdAt: Date.now(),
      lastActivity: Date.now()
    };

    try {
        await db.collection('sessions').doc(code).set(newSession);
        handleSelectSession(code, false);
        setCreatedSessionCode(code);
        setIsVerifyingConnection(true); 
        setConnectionSuccess(false);
    } catch (error) {
        console.error("Error creating session:", error);
        addToast("Failed to create session. Check your connection.", 'error');
