Check this if it is helpful:
WhatsApp’s voice recording and sending feature is built into the official app and is not something you can implement by writing your own “WhatsApp code” — the source code is proprietary and not publicly available.
However, if you want to build your own app (or a prototype) that lets a user record their voice and send it to a friend (similar to WhatsApp), you can do that using standard programming tools and APIs.
Below is a complete runnable example in Java (Android) that records audio from the microphone, saves it, and sends it via a share intent (which could include WhatsApp if installed).

Android Example: Record and Send Voice Message
Javapackage com.example.voicemessenger;

import android.Manifest;
import android.content.Intent;
import android.content.pm.PackageManager;
import android.media.MediaRecorder;
import android.net.Uri;
import android.os.Bundle;
import android.os.Environment;
import android.view.View;
import android.widget.Button;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.app.ActivityCompat;
import androidx.core.content.ContextCompat;

import java.io.File;
import java.io.IOException;

public class MainActivity extends AppCompatActivity {

    private static final int REQUEST_PERMISSION_CODE = 1000;
    private MediaRecorder mediaRecorder;
    private String audioFilePath;
    private boolean isRecording = false;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        Button recordBtn = findViewById(R.id.recordBtn);
        Button sendBtn = findViewById(R.id.sendBtn);

        // Set file path for recorded audio
        audioFilePath = getExternalFilesDir(Environment.DIRECTORY_MUSIC) + "/voice_message.3gp";

        recordBtn.setOnClickListener(v -> {
            if (checkPermissions()) {
                if (!isRecording) {
                    startRecording();
                    recordBtn.setText("Stop Recording");
                } else {
                    stopRecording();
                    recordBtn.setText("Start Recording");
                }
            } else {
                requestPermissions();
            }
        });

        sendBtn.setOnClickListener(v -> sendAudio());
    }

    private void startRecording() {
        try {
            mediaRecorder = new MediaRecorder();
            mediaRecorder.setAudioSource(MediaRecorder.AudioSource.MIC);
            mediaRecorder.setOutputFormat(MediaRecorder.OutputFormat.THREE_GPP);
            mediaRecorder.setOutputFile(audioFilePath);
            mediaRecorder.setAudioEncoder(MediaRecorder.AudioEncoder.AMR_NB);
            mediaRecorder.prepare();
            mediaRecorder.start();
            isRecording = true;
            Toast.makeText(this, "Recording started...", Toast.LENGTH_SHORT).show();
        } catch (IOException e) {
            e.printStackTrace();
            Toast.makeText(this, "Recording failed!", Toast.LENGTH_SHORT).show();
        }
    }

    private void stopRecording() {
        if (mediaRecorder != null) {
            mediaRecorder.stop();
            mediaRecorder.release();
            mediaRecorder = null;
            isRecording = false;
            Toast.makeText(this, "Recording saved.", Toast.LENGTH_SHORT).show();
        }
    }

    private void sendAudio() {
        File audioFile = new File(audioFilePath);
        if (!audioFile.exists()) {
            Toast.makeText(this, "No recording found!", Toast.LENGTH_SHORT).show();
            return;
        }

        Intent shareIntent = new Intent(Intent.ACTION_SEND);
        shareIntent.setType("audio/3gpp");
        Uri uri = Uri.fromFile(audioFile);
        shareIntent.putExtra(Intent.EXTRA_STREAM, uri);
        startActivity(Intent.createChooser(shareIntent, "Send voice message via"));
    }

    private boolean checkPermissions() {
        int recordPermission = ContextCompat.checkSelfPermission(this, Manifest.permission.RECORD_AUDIO);
        int storagePermission = ContextCompat.checkSelfPermission(this, Manifest.permission.WRITE_EXTERNAL_STORAGE);
        return recordPermission == PackageManager.PERMISSION_GRANTED &&
               storagePermission == PackageManager.PERMISSION_GRANTED;
    }

    private void requestPermissions() {
        ActivityCompat.requestPermissions(this,
                new String[]{Manifest.permission.RECORD_AUDIO, Manifest.permission.WRITE_EXTERNAL_STORAGE},
                REQUEST_PERMISSION_CODE);
    }

    @Override
    public void onRequestPermissionsResult(int requestCode, @NonNull String[] permissions, @NonNull int[] grantResults) {
        super.onRequestPermissionsResult(requestCode, permissions, grantResults);
        if (requestCode == REQUEST_PERMISSION_CODE) {
            if (grantResults.length > 0 && grantResults[0] == PackageManager.PERMISSION_GRANTED) {
                Toast.makeText(this, "Permissions granted.", Toast.LENGTH_SHORT).show();
            } else {
                Toast.makeText(this, "Permissions denied.", Toast.LENGTH_SHORT).show();
            }
        }
    }
}


How it works

Record Button — Starts/stops recording using MediaRecorder.
Send Button — Opens a share dialog so the user can send the audio file via WhatsApp, email, etc.
Permissions — Requests microphone and storage permissions at runtime.
File Format — Saves as .3gp for small file size and compatibility.


