  addToast: (message: string, type: Toast['type']) => void;
  onActionAttempt: (action: () => Promise<void>) => void;
  activeCode: string | null;
  setActiveCode: (code: string | null) => void;
  notes: Note[];
  setNotes: (notes: Note[]) => void;
}

interface Message {
  id: string;
  sender: string;
  senderProfilePicture?: string | null;
  text: string;
  image?: string | null;
  audio?: string | null; // URL for audio file
  fileData?: string | null;
  fileName?: string | null;
  fileType?: string | null;
  timestamp: number;
  type: 'text' | 'image' | 'ai' | 'file' | 'audio' | 'system';
  hiddenFor?: string[]; // Array of usernames who deleted this for themselves
}

interface Participant {
  name: string;
  photo?: string | null;
}

interface SessionData {
  code: string;
  creator: string;
  participants: Participant[];
  participantNames: string[];
  activeParticipants?: Record<string, number>; 
  messages: Message[];
  typing?: Record<string, boolean>;
  createdAt: number;
  lastMessage?: Message;
  lastActivity?: number;
}

const COMMON_EMOJIS = ["😀", "😂", "🤣", "😊", "😍", "🤔", "😎", "😭", "👍", "👎", "👋", "🙏", "🔥", "✨", "🎉", "💯", "❤️", "💔", "🎓", "📚", "🧠", "💡", "✅", "❌"];

export function CollaborativeSession({ userDetails, addToast, onActionAttempt, activeCode, setActiveCode, notes, setNotes }: CollaborativeSessionProps) {
  // View State
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');

  // Data State
  const [sessionHistory, setSessionHistory] = useState<SessionData[]>([]);
  const [sessionCode, setSessionCode] = useState('');
  const [sessionData, setSessionData] = useState<SessionData | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);

  // Input State
  const [inputCode, setInputCode] = useState('');
  const [newMessage, setNewMessage] = useState('');
  const [isAIThinking, setIsAIThinking] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [showLeaveConfirm, setShowLeaveConfirm] = useState(false);
  const [showJoinModal, setShowJoinModal] = useState(false);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);

  // Voice Recording State
  const [isRecording, setIsRecording] = useState(false);
  const [recordingTime, setRecordingTime] = useState(0);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const timerIntervalRef = useRef<any>(null);

  // Typing Indicator State
  const typingTimeoutRef = useRef<any>(null);
  const [activeTypers, setActiveTypers] = useState<string[]>([]);

  // Editing & Deleting State
  const [editingMessageId, setEditingMessageId] = useState<string | null>(null);
  const [editMessageText, setEditMessageText] = useState('');
  const [sessionToDelete, setSessionToDelete] = useState<string | null>(null);
  const [messageToDelete, setMessageToDelete] = useState<Message | null>(null);

  // Invite & Pairing State
  const [createdSessionCode, setCreatedSessionCode] = useState<string | null>(null);
  const [showShareConfirm, setShowShareConfirm] = useState(false);

  // Strict Verification & View Mode State
  const [isVerifyingConnection, setIsVerifyingConnection] = useState(false);
  const [connectionSuccess, setConnectionSuccess] = useState(false);
  const [isViewOnly, setIsViewOnly] = useState(false);
  const [historyActionSession, setHistoryActionSession] = useState<SessionData | null>(null);

  // Refs
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const unsubscribeRef = useRef<(() => void) | null>(null);
  const [shouldAutoScroll, setShouldAutoScroll] = useState(true);

  // --- Scroll Logic ---
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  const handleScroll = () => {
      if (scrollContainerRef.current) {
          const { scrollTop, scrollHeight, clientHeight } = scrollContainerRef.current;
          // If within 100px of bottom, enable auto-scroll
          const isNearBottom = scrollHeight - scrollTop - clientHeight < 100;
          setShouldAutoScroll(isNearBottom);
      }
  };

  useEffect(() => {
      if (shouldAutoScroll) {
          scrollToBottom();
      }
  }, [messages, activeTypers, shouldAutoScroll]);

  // --- Initialization & History Fetching ---

  useEffect(() => {
    if (!userDetails?.name) return;

    const unsubscribeHistory = db.collection('sessions')
      .where('participantNames', 'array-contains', userDetails.name)
      .onSnapshot((snapshot) => {
        const history = snapshot.docs.map(doc => ({ ...doc.data(), code: doc.id } as SessionData));
        // Sort client-side by lastActivity desc
        history.sort((a, b) => (b.lastActivity || 0) - (a.lastActivity || 0));
        setSessionHistory(history);
      }, (error) => {
        console.error("Error fetching history:", error);
      });

    return () => unsubscribeHistory();
  }, [userDetails?.name]);

  useEffect(() => {
    if (activeCode) {
      setSessionCode(activeCode);
      setIsSidebarOpen(false);
      setIsViewOnly(false);
      setIsVerifyingConnection(true);
    }
  }, [activeCode]);

  // --- HEARTBEAT SYSTEM ---
  useEffect(() => {
      if (sessionCode && userDetails && !isViewOnly) {
          const sessionRef = db.collection('sessions').doc(sessionCode);

          const sendHeartbeat = () => {
              sessionRef.update({
                  [`activeParticipants.${userDetails.name}`]: Date.now()
              }).catch(e => console.warn("Heartbeat failed", e));
          };

          sendHeartbeat();
          const heartbeatInterval = setInterval(sendHeartbeat, 10000);

          const cleanup = () => {
              if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
              clearInterval(heartbeatInterval);
              sessionRef.update({
                  [`activeParticipants.${userDetails.name}`]: firebase.firestore.FieldValue.delete(),
                  [`typing.${userDetails.name}`]: firebase.firestore.FieldValue.delete()
              }).catch(e => console.warn("Cleanup failed", e));
          };

          window.addEventListener('beforeunload', cleanup);
          return () => {
              window.removeEventListener('beforeunload', cleanup);
              cleanup();
          };
      }
  }, [sessionCode, userDetails, isViewOnly]);

  // Click outside listener for emoji picker
  useEffect(() => {
      const closePicker = (e: any) => {
          if (showEmojiPicker && !e.target.closest('.emoji-picker-container')) {
              setShowEmojiPicker(false);
          }
      }
      document.addEventListener('mousedown', closePicker);
      return () => document.removeEventListener('mousedown', closePicker);
  }, [showEmojiPicker]);

  // --- Helpers ---

  const sendSystemMessage = async (text: string, code: string = sessionCode) => {
      if (!code) return;
      const systemMsg: Message = {
          id: Date.now().toString(),
          sender: 'System',
          text: text,
          timestamp: Date.now(),
          type: 'system',
          audio: null, image: null, fileData: null, fileName: null, fileType: null
      };
      try {
          await db.collection('sessions').doc(code).update({
              messages: firebase.firestore.FieldValue.arrayUnion(systemMsg),
              lastActivity: Date.now()
          });
      } catch (e) { console.error("Failed to send system message", e); }
  };

  const updateTypingStatus = async (isTyping: boolean) => {
      if (!sessionCode || !userDetails || isViewOnly) return;
      try {
          await db.collection('sessions').doc(sessionCode).update({
              [`typing.${userDetails.name}`]: isTyping ? true : firebase.firestore.FieldValue.delete()
          });
      } catch (e) { }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      setNewMessage(e.target.value);
      if (!sessionCode || isViewOnly) return;
      updateTypingStatus(true);
      if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
      typingTimeoutRef.current = setTimeout(() => { updateTypingStatus(false); }, 2000);
  };

  const handleEmojiClick = (emoji: string) => {
      if (isViewOnly) return;
      setNewMessage(prev => prev + emoji);
      updateTypingStatus(true);
      if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
      typingTimeoutRef.current = setTimeout(() => { updateTypingStatus(false); }, 2000);
  };

  // --- Session Management Logic ---

  const generateCode = () => {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    let code = '';
    for (let i = 0; i < 6; i++) {
      code += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return code;
  };

  const createSession = async () => {
    if (!userDetails?.name) {
      addToast('Please ensure your profile name is set.', 'error');
      return;
    }

    const code = generateCode();
    const participant: Participant = {
        name: userDetails.name,
        photo: userDetails.profilePicture || null
    };

    const newSession: SessionData = {
      code,
      creator: userDetails.name,
      participants: [participant],
      participantNames: [userDetails.name],
      activeParticipants: { [userDetails.name]: Date.now() },
      messages: [],
      typing: {},
      createdAt: Date.now(),
      lastActivity: Date.now()
    };

    try {
        await db.collection('sessions').doc(code).set(newSession);
        handleSelectSession(code, false);
        setCreatedSessionCode(code);
        setIsVerifyingConnection(true); 
        setConnectionSuccess(false);
    } catch (error) {
        console.error("Error creating session:", error);
        addToast("Failed to create session. Check your connection.", 'error');
    }
  };

  const joinSession = async () => {
    if (!userDetails?.name) return;
    if (!inputCode.trim()) {
      addToast('Please enter session code', 'warning');
      return;
    }

    if (!navigator.onLine) {
      addToast('You are offline. Please connect to the internet to join a session.', 'error');
      return;
    }

    const code = inputCode.toUpperCase();
    const sessionRef = db.collection('sessions').doc(code);

    try {
        const doc = await sessionRef.get();
        if (!doc.exists) {
            addToast('Session not found.', 'error');
            return;
        }
        const session = doc.data() as SessionData;
        if (!session.participantNames?.includes(userDetails.name)) {
            const newParticipant: Participant = {
                name: userDetails.name,
                photo: userDetails.profilePicture || null
            };
            await sessionRef.update({
                participants: firebase.firestore.FieldValue.arrayUnion(newParticipant),
                participantNames: firebase.firestore.FieldValue.arrayUnion(userDetails.name),
                [`activeParticipants.${userDetails.name}`]: Date.now(),
                lastActivity: Date.now()
            });
            await sendSystemMessage(`${userDetails.name} joined the session.`, code);
        }
        setShowJoinModal(false);
        setInputCode('');
        handleSelectSession(code, false);
        addToast("Successfully paired!", 'success');
    } catch (error: any) {
        addToast("Failed to join session.", 'error');
    }
  };

  const onHistoryItemClick = (session: SessionData) => {
      if (session.code === activeCode) {
          setIsSidebarOpen(false);
          return;
      }
      setHistoryActionSession(session);
  };

  const handleHistoryAction = (action: 'view' | 'connect') => {
      if (!historyActionSession) return;
      if (action === 'view') {
          handleSelectSession(historyActionSession.code, true);
          addToast("Viewing chat history.", 'info');
      } else {
          handleSelectSession(historyActionSession.code, false);
          setCreatedSessionCode(historyActionSession.code);
          setIsVerifyingConnection(true);
          setConnectionSuccess(false);
      }
      setHistoryActionSession(null);
  };

  const handleSelectSession = (code: string, viewOnly: boolean) => {
      setSessionCode(code);
      setIsViewOnly(viewOnly);
      setIsSidebarOpen(false);
      if (viewOnly) {
          setIsVerifyingConnection(false);
          setConnectionSuccess(true);
          setActiveCode(null);
      } else {
          setActiveCode(code);
          setIsVerifyingConnection(true); 
          setConnectionSuccess(false);
      }
  };

  const shareCode = async (codeOverride?: string) => {
      const explicitCode = typeof codeOverride === 'string' ? codeOverride : undefined;
      const codeToShare = explicitCode || createdSessionCode || sessionCode;
      if (!codeToShare) { addToast("No code available.", 'error'); return; }
      const shareData: ShareData = { title: 'Join my Study Session', text: `My Pairing Code: ${codeToShare}` };
      if (window.location.protocol.startsWith('http')) shareData.url = window.location.href;
      if (navigator.share) { try { await navigator.share(shareData); } catch (err: any) { if (err.name !== 'AbortError') addToast("Unable to share.", 'error'); } } else { copyCode(codeToShare); }
  };

  const copyCode = (codeToCopy: string = sessionCode) => {
    if (!codeToCopy) return;
    navigator.clipboard.writeText(codeToCopy).then(() => addToast("Copied!", 'success')).catch(() => addToast("Failed to copy.", 'error'));
  };

  const handleStartChattingClick = () => setShowShareConfirm(true);
  const confirmShared = () => { setShowShareConfirm(false); setCreatedSessionCode(null); };

  // --- Recording Logic ---
  const startRecording = async () => {
    if (isViewOnly) return;
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) { addToast('Audio not supported.', 'error'); return; }
    try {
      updateTypingStatus(false);
      if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];
      mediaRecorder.ondataavailable = (e) => { if (e.data.size > 0) audioChunksRef.current.push(e.data); };
      mediaRecorder.start();
      setIsRecording(true);
      setRecordingTime(0);
      timerIntervalRef.current = setInterval(() => { setRecordingTime(prev => prev + 1); }, 1000);
    } catch (error) { addToast('Microphone access denied.', 'error'); }
  };

  const stopAndSendRecording = async () => {
    if (!mediaRecorderRef.current || !sessionCode || !userDetails || isViewOnly) return;

    setIsRecording(false);
    if (timerIntervalRef.current) clearInterval(timerIntervalRef.current);

    const mimeType = mediaRecorderRef.current.mimeType || 'audio/webm';
    const extension = mimeType.includes('mp4') ? 'mp4' : 'webm';

    // Use promise to wait for onstop event to ensure blob is constructed
    const stopPromise = new Promise<Blob>((resolve) => {
        mediaRecorderRef.current!.onstop = () => {
            const audioBlob = new Blob(audioChunksRef.current, { type: mimeType });
            audioChunksRef.current = []; // Clear
            resolve(audioBlob);
        };
    });

    mediaRecorderRef.current.stop();
    mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop());

    setIsUploading(true);

    try {
        const audioBlob = await stopPromise;
        if (audioBlob.size === 0) {
             addToast("Recording empty.", 'warning');
             return;
        }

        const audioFile = new File([audioBlob], `audio_${Date.now()}.${extension}`, { type: mimeType });
        const storageRef = storage.ref();
        const fileRef = storageRef.child(`sessions/${sessionCode}/audio/${audioFile.name}`);

        await fileRef.put(audioFile);
        const downloadURL = await fileRef.getDownloadURL();

        const message: Message = { 
            id: Date.now().toString(), 
            sender: userDetails.name, 
            senderProfilePicture: userDetails.profilePicture || null, 
            text: '🎤 Voice Message', 
            audio: downloadURL, 
            timestamp: Date.now(), 
            type: 'audio', 
            image: null, fileData: null, fileName: null, fileType: null 
        };

        setShouldAutoScroll(true);
        await db.collection('sessions').doc(sessionCode).update({ 
            messages: firebase.firestore.FieldValue.arrayUnion(message), 
            lastMessage: message, 
            lastActivity: Date.now() 
        });
    } catch (error: any) { 
        console.error(error);
        if (error.code === 'storage/retry-limit-exceeded') {
            addToast("Upload timed out. Please check your connection and try again.", 'error');
        } else {
            addToast("Failed to send voice message.", 'error'); 
        }
    } finally { 
        setIsUploading(false); 
    }
  };

  const cancelRecording = () => {
    if (mediaRecorderRef.current && isRecording) { mediaRecorderRef.current.stop(); mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop()); }
    setIsRecording(false); if (timerIntervalRef.current) clearInterval(timerIntervalRef.current); updateTypingStatus(false); audioChunksRef.current = [];
  };

  const formatDuration = (seconds: number) => { const mins = Math.floor(seconds / 60); const secs = seconds % 60; return `${mins}:${secs.toString().padStart(2, '0')}`; };

  // --- Messaging Logic ---
  const sendMessage = async () => {
    if (!newMessage.trim() || !sessionCode || !userDetails || isViewOnly) return;
    const textToSend = newMessage; setNewMessage(''); if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current); updateTypingStatus(false);
    setShouldAutoScroll(true);
    const message: Message = { id: Date.now().toString(), sender: userDetails.name, senderProfilePicture: userDetails.profilePicture || null, text: textToSend, timestamp: Date.now(), type: 'text', image: null, fileData: null, fileName: null, fileType: null, audio: null };
    try { await db.collection('sessions').doc(sessionCode).update({ messages: firebase.firestore.FieldValue.arrayUnion(message), lastMessage: message, lastActivity: Date.now() }); } catch (error) { addToast("Failed to send message.", 'error'); }
  };

  const handleEditMessage = async (messageId: string, newText: string) => {
      if (!sessionCode || isViewOnly) return;
      try {
          const docRef = db.collection('sessions').doc(sessionCode);
          const doc = await docRef.get();
          if (doc.exists) {
              const data = doc.data() as SessionData;
              const updatedMessages = data.messages.map(m => m.id === messageId ? { ...m, text: newText } : m);
              await docRef.update({ messages: updatedMessages });
              setEditingMessageId(null); setEditMessageText('');
          }
      } catch (error) { addToast("Failed to edit.", 'error'); }
  };

  const handleDeleteMessage = async (deleteForEveryone: boolean) => {
      if (!sessionCode || !messageToDelete || isViewOnly || !userDetails) return;

      try {
          const docRef = db.collection('sessions').doc(sessionCode);
          const doc = await docRef.get();

          if (doc.exists) {
              const data = doc.data() as SessionData;
              let updatedMessages = [...data.messages];

              if (deleteForEveryone) {
                  updatedMessages = updatedMessages.filter(m => m.id !== messageToDelete.id);
              } else {
                   updatedMessages = updatedMessages.map(m => {
                       if (m.id === messageToDelete.id) {
                           const currentHidden = m.hiddenFor || [];
                           if (!currentHidden.includes(userDetails.name)) {
                               return { ...m, hiddenFor: [...currentHidden, userDetails.name] };
                           }
                       }
                       return m;
                   });
              }

              const newLastMessage = updatedMessages.length > 0 ? updatedMessages[updatedMessages.length - 1] : null;

              await docRef.update({ 
                  messages: updatedMessages,
                  lastMessage: newLastMessage || firebase.firestore.FieldValue.delete()
              });

              addToast(deleteForEveryone ? "Message deleted for everyone." : "Message deleted for you.", 'success');
          }
      } catch (error) { 
          addToast("Failed to delete message.", 'error'); 
      } finally {
          setMessageToDelete(null);
      }
  };

  const handleDeleteSession = async (codeToDelete: string) => {
      if (!userDetails) return;
      try {
        setSessionHistory(prev => prev.filter(s => s.code !== codeToDelete));
        if (sessionCode === codeToDelete) { setActiveCode(null); setSessionCode(''); setSessionData(null); setMessages([]); setIsSidebarOpen(true); }
        const sessionRef = db.collection('sessions').doc(codeToDelete);
        const doc = await sessionRef.get();
        if (doc.exists) {
            const data = doc.data() as SessionData;
            const participantToRemove = data.participants.find(p => p.name === userDetails.name);
            if (participantToRemove) {
                await sessionRef.update({
                    participants: firebase.firestore.FieldValue.arrayRemove(participantToRemove),
                    participantNames: firebase.firestore.FieldValue.arrayRemove(userDetails.name)
                });
            }
        }
        setSessionToDelete(null); addToast("Chat deleted.", 'success');
      } catch (error) { addToast("Failed to delete chat.", 'error'); }
  };

  const handleSaveToNotes = (text: string) => {
    const newNote: Note = { id: Date.now().toString(), title: `Chat from Session ${sessionCode}`, content: text, subject: 'Collaborative Session', createdAt: new Date().toISOString(), isFavourite: false };
    setNotes([newNote, ...notes]); addToast('Saved to notes!', 'success');
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !sessionCode || !userDetails || isViewOnly) return;
    if (file.size > 50 * 1024 * 1024) { addToast("File > 50MB.", 'error'); return; }
    setIsUploading(true);
    try {
        const storageRef = storage.ref();
        const fileRef = storageRef.child(`sessions/${sessionCode}/${Date.now()}_${file.name}`);
        await fileRef.put(file);
        const downloadURL = await fileRef.getDownloadURL();
        const isImage = file.type.startsWith('image/');
        const message: Message = { 
            id: Date.now().toString(), 
            sender: userDetails.name, 
            senderProfilePicture: userDetails.profilePicture || null, 
            text: isImage ? '📷 Photo' : `📄 ${file.name}`, 
            image: isImage ? downloadURL : null, 
            fileData: !isImage ? downloadURL : null, 
            fileName: file.name || 'unknown', 
            fileType: file.type || 'application/octet-stream', 
            timestamp: Date.now(), 
            type: isImage ? 'image' : 'file',
            audio: null 
        };
        setShouldAutoScroll(true);
        await db.collection('sessions').doc(sessionCode).update({ messages: firebase.firestore.FieldValue.arrayUnion(message), lastMessage: message, lastActivity: Date.now() });
        await sendSystemMessage(`${userDetails.name} uploaded ${file.name}`);
    } catch (error: any) { 
        console.error(error);
        if (error.code === 'storage/retry-limit-exceeded') {
            addToast("Upload timed out. Please check your connection and try again.", 'error');
        } else {
            addToast("Upload failed.", 'error');
        }
    } finally { setIsUploading(false); if (e.target) e.target.value = ''; }
  };

  const askAI = async () => {
    if (messages.length === 0) { addToast('Start a conversation first!', 'info'); return; }
    if (isViewOnly) return;
    setIsAIThinking(true);
    const conversationContext = messages.slice(-20).map(m => `${m.sender}: ${m.text}`).join('\n');
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY! });
      const prompt = `You are Blay, a study AI. Context:\n${conversationContext}\nResponse:`;
      const response = await ai.models.generateContent({ model: 'gemini-2.5-flash', contents: prompt });
      const aiMessage: Message = { id: Date.now().toString(), sender: 'EduBlay AI', text: response.text, timestamp: Date.now(), type: 'ai', image: null, fileData: null, fileName: null, fileType: null, audio: null };
      await db.collection('sessions').doc(sessionCode).update({ messages: firebase.firestore.FieldValue.arrayUnion(aiMessage), lastMessage: aiMessage, lastActivity: Date.now() });
    } catch (error) { addToast('AI failed.', 'error'); } finally { setIsAIThinking(false); }
  };

  // --- Navigation & Cleanup ---
  const handleLeaveRequest = () => setShowLeaveConfirm(true);
  const handleConfirmLeave = async () => {
    setShowLeaveConfirm(false);
    if (unsubscribeRef.current) unsubscribeRef.current();
    if (sessionCode && userDetails && !isViewOnly) {
         try {
            await sendSystemMessage(`${userDetails.name} left the session.`, sessionCode);
            const participantToRemove: Participant = { name: userDetails.name, photo: userDetails.profilePicture || null };
            await db.collection('sessions').doc(sessionCode).update({
                participants: firebase.firestore.FieldValue.arrayRemove(participantToRemove),
                participantNames: firebase.firestore.FieldValue.arrayRemove(userDetails.name),
                [`activeParticipants.${userDetails.name}`]: firebase.firestore.FieldValue.delete(),
                [`typing.${userDetails.name}`]: firebase.firestore.FieldValue.delete()
            });
        } catch (e) { }
    }
    setActiveCode(null); setSessionCode(''); setSessionData(null); setMessages([]); setIsSidebarOpen(true);
  };

  useEffect(() => {
    if (sessionCode) {
      if (!isViewOnly) setIsVerifyingConnection(true);
      const unsubscribe = db.collection('sessions').doc(sessionCode)
        .onSnapshot((doc) => {
            if (doc.exists) {
                const data = doc.data() as SessionData;
                setSessionData(data);

                const visibleMessages = (data.messages || []).filter(m => !m.hiddenFor?.includes(userDetails?.name || ''));
                setMessages(visibleMessages);

                if (data.typing && userDetails) {
                    const typers = Object.keys(data.typing).filter(name => name !== userDetails.name && data.typing![name]);
                    setActiveTypers(typers);
                } else { setActiveTypers([]); }

                if (!isViewOnly) {
                    const activeMap = data.activeParticipants || {};
                    const now = Date.now();
                    const activeCount = Object.values(activeMap).filter(ts => now - ts < 60000).length;
                    if (activeCount >= 2) {
                        setIsVerifyingConnection(false);
                        setConnectionSuccess(true);
                    } else {
                        setIsVerifyingConnection(true);
                        setConnectionSuccess(false);
                    }
                }
            } else {
                addToast("Session ended.", 'info');
                setActiveCode(null); setSessionCode(''); setIsSidebarOpen(true);
            }
        });
      unsubscribeRef.current = unsubscribe;
      return () => unsubscribe();
    }
  }, [sessionCode, setActiveCode, userDetails, isViewOnly]); 

  const formatTime = (timestamp: number) => new Date(timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  const getInitials = (name: string) => name ? name.charAt(0).toUpperCase() : '?';
  const getOtherParticipant = (session: SessionData) => {
      if (!userDetails) return null;
      if (session.participants.length > 2) return null; 
      return session.participants.find(p => p.name !== userDetails.name);
  };
  const startEditing = (msg: Message) => { setEditingMessageId(msg.id); setEditMessageText(msg.text); };
  const startDeleting = (msg: Message) => { setMessageToDelete(msg); };

  const filteredHistory = useMemo(() => {
      return sessionHistory.filter(session => {
          const names = session.participants.map(p => p.name).join(' ').toLowerCase();
          return names.includes(searchQuery.toLowerCase()) || session.code.toLowerCase().includes(searchQuery.toLowerCase());
      });
  }, [sessionHistory, searchQuery]);

  return (
    <div className="h-[calc(100vh-90px)] flex bg-white dark:bg-gray-900 rounded-2xl shadow-xl overflow-hidden border dark:border-gray-700 -mx-4 sm:mx-0">
