                        <div className="flex items-center gap-3" onClick={() => copyCode()} title="Copy code">
                             {(() => { const other = sessionData ? getOtherParticipant(sessionData) : null; if(!other) return <div className="w-10 h-10 bg-indigo-100 dark:bg-indigo-900 text-indigo-600 rounded-full flex items-center justify-center"><Users className="w-5 h-5" /></div>; if(other?.photo) return <img src={other.photo} className="w-10 h-10 rounded-full object-cover" alt={other.name} />; return <div className="w-10 h-10 bg-purple-100 dark:bg-purple-900 text-purple-600 rounded-full flex items-center justify-center font-bold">{getInitials(other?.name || '?')}</div>; })()}
