      {historyActionSession && <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4"><div className="bg-white dark:bg-gray-800 rounded-xl p-6 w-full max-w-sm shadow-2xl"><h3 className="text-lg font-bold mb-2 dark:text-white">Session Options</h3><p className="text-gray-600 dark:text-gray-400 mb-6 text-sm">Do you want to view the chat history or reconnect with your partner?</p><div className="space-y-3"><button onClick={() => handleHistoryAction('view')} className="w-full flex items-center justify-center gap-2 py-3 bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300 rounded-lg font-semibold hover:bg-blue-200 dark:hover:bg-blue-900/50 transition-colors"><EyeIcon className="w-5 h-5" /> View Chat (Read-Only)</button><button onClick={() => handleHistoryAction('connect')} className="w-full flex items-center justify-center gap-2 py-3 bg-green-600 text-white rounded-lg font-semibold hover:bg-green-700 transition-colors"><LinkIcon className="w-5 h-5" /> Connect & Chat</button><button onClick={() => setHistoryActionSession(null)} className="w-full py-2 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:text-gray-200 text-sm">Cancel</button></div></div></div>}
      <ConfirmationModal isOpen={showLeaveConfirm} onClose={() => setShowLeaveConfirm(false)} onConfirm={handleConfirmLeave} title="Leave Chat?" message="You can rejoin later using the session code." confirmText="Leave" confirmColor="red" />
