          if (doc.exists) {
              const data = doc.data() as SessionData;
              const updatedMessages = data.messages.map(m => m.id === messageId ? { ...m, text: newText } : m);
              await docRef.update({ messages: updatedMessages });
              setEditingMessageId(null); setEditMessageText('');
          }
