                          <button onClick={() => { setViewMode(viewMode === 'signUp' ? 'signIn' : 'signUp'); setErrors({}); setMessage(''); }} className="font-medium text-primary hover:text-primary-dark dark:text-primary-light dark:hover:text-primary transition-colors">
                            {viewMode === 'signUp' ? t('auth.signIn') : t('auth.signUp')}
                          </button>
                      </div>
                  </div>
              )}

              <ConfirmationModal
                  isOpen={showConflictModal}
                  onClose={() => { setShowConflictModal(false); setIsSubmitting(false); }}
                  onConfirm={handleForceLogin}
                  title="Account Active Elsewhere"
                  message="Your account is currently logged in on another device. Do you want to log out the other device and sign in here? (Is this you?)"
                  confirmText="Yes, Log Me In"
                  cancelText="No, Cancel"
                  confirmColor="red"
              />
          </div>
      </div>
  );
};

export default SignUp;
