import { db } from './firebase';
import firebase from 'firebase/compat/app';
import type { UserDetails } from '../../types.ts';
import { EducationalLevel } from '../../types.ts';
import { globalFeedbackService } from './globalFeedbackService';
import { initializeUsage } from '../../lib/usageManager';
import { initializeGamification } from '../../lib/gamification';

// --- SECURITY & SYNC SERVICE ---

const SESSION_TOKEN_KEY = 'sessionToken';
const LOCAL_SESSION_ID_KEY = 'device_session_id';

/**
 * Simple obfuscation to prevent casual tampering in LocalStorage.
 * NOT suitable for storing highly sensitive data like credit cards, but good for app state.
 */
const encrypt = (data: any): string => {
    try {
        const json = JSON.stringify(data);
        return btoa(encodeURIComponent(json)); // Base64 encode
    } catch (e) {
        return '';
    }
};

const decrypt = <T>(data: string): T | null => {
    try {
        const json = decodeURIComponent(atob(data));
        return JSON.parse(json);
    } catch (e) {
        return null;
    }
};

/**
 * Generates a random session ID to track specific device logins.
 */
const generateSessionId = () => {
    return Math.random().toString(36).substring(2) + Date.now().toString(36);
};

/**
 * Saves the current session ID to local storage for validation.
 */
const setLocalSessionId = (id: string) => {
    localStorage.setItem(LOCAL_SESSION_ID_KEY, id);
};

/**
 * Gets the current session ID from local storage.
 */
const getLocalSessionId = () => {
    return localStorage.getItem(LOCAL_SESSION_ID_KEY);
};

// --- Cloud Storage Service (Firestore Wrapper) ---

export const storageService = {
    /**
     * Save specific user data to Firestore.
     */
    saveUserData: async (userId: string, data: Partial<any>) => {
        if (!userId || !navigator.onLine) return;
        try {
            await db.collection('users').doc(userId).set(data, { merge: true });
        } catch (error) {
            console.error("Failed to sync data to cloud:", error);
        }
    },

    /**
     * Load full user data from Firestore.
     */
    loadUserData: async (userId: string): Promise<any | null> => {
        try {
            const doc = await db.collection('users').doc(userId).get();
            if (doc.exists) {
                return doc.data();
            }
            return null;
        } catch (error) {
            console.error("Failed to load cloud data:", error);
            return null;
        }
    },

    updateHeartbeat: async (userId: string) => {
        if (!userId || !navigator.onLine) return;
        try {
            await db.collection('users').doc(userId).update({
                lastActive: firebase.firestore.FieldValue.serverTimestamp()
            });
        } catch (e) {
            // Silent fail for heartbeat
        }
    },

    saveLocalItem: (key: string, value: any) => {
        try {
            localStorage.setItem(key, JSON.stringify(value));
        } catch (e) { console.error(e); }
    },

    loadLocalItem: <T>(key: string): T | null => {
        try {
            const item = localStorage.getItem(key);
            return item ? JSON.parse(item) : null;
        } catch (e) { return null; }
    },

    saveItem: (key: string, value: any) => {
        try {
            const encrypted = encrypt(value);
            localStorage.setItem(key, encrypted);
        } catch (error) {
            console.error(`Failed to save item "${key}"`, error);
        }
    },

    loadItem: <T>(key: string): T | null => {
        try {
            const item = localStorage.getItem(key);
            if (!item) return null;
            const decrypted = decrypt<T>(item);
            if (decrypted) return decrypted;
            return JSON.parse(item); // Fallback
        } catch (error) {
            return null;
        }
    },

    removeItem: (key: string) => {
        localStorage.removeItem(key);
    },

    exportAllData: async () => {
        const user = getCurrentUser();
        if (!user?.id) throw new Error("No user logged in");
        const data = await storageService.loadUserData(user.id);
        if (data) {
            storageService.formatExportData(data);
        } else {
            throw new Error("No data found to export");
        }
    },

    importAllData: async (file: File) => {
        const user = getCurrentUser();
        if (!user?.id) throw new Error("No user logged in");

        return new Promise<void>((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = async (event) => {
                try {
                    const data = JSON.parse(event.target?.result as string);
                    await storageService.saveUserData(user.id, data);
                    Object.keys(data).forEach(key => {
                         storageService.saveItem(key, data[key]);
                    });
                    resolve();
                } catch (error) {
                    reject(new Error("Failed to parse or save import file."));
                }
            };
            reader.onerror = () => reject(new Error("Failed to read the import file."));
            reader.readAsText(file);
        });
    },

    clearAllData: async () => {
        localStorage.clear();
    },

    formatExportData: (data: any) => {
        const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `edublay_backup_${new Date().toISOString().split('T')[0]}.json`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    }
};

// --- Authentication Logic ---

const createToken = (user: UserDetails): string => {
    return encrypt(user);
};

const decodeToken = (token: string): UserDetails | null => {
    return decrypt<UserDetails>(token);
};

export const signUp = async (
    name: string,
    email: string,
    password_param: string,
    recoveryQuestion: string,
    recoveryAnswer: string
): Promise<UserDetails> => {
    // 1. Check if user exists in Firestore
    const snapshot = await db.collection('users').where('email', '==', email).get();

    if (!snapshot.empty) {
        throw new Error('Email already registered');
    }

    // 2. Create new user object
    const userId = db.collection('users').doc().id; 
    const sessionId = generateSessionId();

    const newUser: UserDetails & { id: string, password?: string, currentSessionId?: string } = {
        id: userId,
        name,
        email,
        password: password_param, // Should be hashed in production
        recoveryQuestion,
        recoveryAnswer,
        educationalLevel: EducationalLevel.UNDERGRADUATE,
        subscriptionTier: 'free',
        subscriptionStatus: 'active',
        usage: initializeUsage(),
        gamification: initializeGamification(),
        currentSessionId: sessionId
    };

    // 3. Save to Cloud
    await db.collection('users').doc(userId).set(newUser);

    // 4. Register Global Stats
    globalFeedbackService.registerUser(userId, name, email);

    // 5. Set Local Session
    setLocalSessionId(sessionId);

    const { password, ...userSession } = newUser;
    const token = createToken(userSession as UserDetails);
    storageService.saveItem(SESSION_TOKEN_KEY, token);

    return userSession as UserDetails;
};

export interface LoginResult {
    success: boolean;
    user?: UserDetails;
    requiresConfirmation?: boolean;
    error?: string;
}

export const login = async (email: string, password_param: string, forceLogin: boolean = false): Promise<LoginResult> => {
    try {
        // 1. Query Firestore
        const snapshot = await db.collection('users')
            .where('email', '==', email)
            .where('password', '==', password_param)
            .get();

        if (snapshot.empty) {
            throw new Error('Invalid email or password');
        }

        const userDoc = snapshot.docs[0];
        const userData = userDoc.data() as UserDetails & { password?: string, lastActive?: any, currentSessionId?: string };

        // 2. CHECK FOR ACTIVE SESSION (Unless forcing)
        if (!forceLogin) {
            const lastActive = userData.lastActive;
            if (lastActive) {
                const now = new Date().getTime();
                // Handle both Firestore Timestamp and Date objects
                const lastActiveTime = lastActive.toDate ? lastActive.toDate().getTime() : new Date(lastActive).getTime();
                const diffMinutes = (now - lastActiveTime) / (1000 * 60);

                // If active in last 2 minutes AND has a session ID
                if (diffMinutes < 2 && userData.currentSessionId) {
                     return { success: false, requiresConfirmation: true };
                }
            }
        }

        // 3. GENERATE NEW SESSION ID (Anti-Fraud)
        const newSessionId = generateSessionId();

        // 4. Update Firestore
        await userDoc.ref.update({
            currentSessionId: newSessionId,
            lastLogin: firebase.firestore.FieldValue.serverTimestamp(),
            lastActive: firebase.firestore.FieldValue.serverTimestamp()
        });

        // 5. Set Local Session
        setLocalSessionId(newSessionId);

        // 6. Register Activity
        if(userData.id) {
            globalFeedbackService.registerUser(userData.id, userData.name, userData.email || '');
        }

        const { password, ...userSession } = userData;
        const token = createToken(userSession);
        storageService.saveItem(SESSION_TOKEN_KEY, token);

        return { success: true, user: userSession };

    } catch (error: any) {
        throw error;
    }
};

export const logout = async () => {
    storageService.removeItem(SESSION_TOKEN_KEY);
    localStorage.removeItem(LOCAL_SESSION_ID_KEY);
};

export const getCurrentUser = (): UserDetails | null => {
    const token = storageService.loadItem<string>(SESSION_TOKEN_KEY);
    if (token) {
        if (typeof token === 'string') {
            const user = decodeToken(token);
            if (user) return user;
             try { return JSON.parse(atob(token)); } catch(e) {}
        }
        return token as unknown as UserDetails;
    }
    return null;
};

// --- ANTI-FRAUD MONITOR ---
export const subscribeToAuthChanges = (userId: string, onForceLogout: () => void) => {
    return db.collection('users').doc(userId).onSnapshot((doc) => {
        if (doc.exists) {
            const data = doc.data();
            const cloudSessionId = data?.currentSessionId;
            const localSessionId = getLocalSessionId();

            if (cloudSessionId && localSessionId && cloudSessionId !== localSessionId) {
                console.warn("Security Alert: Concurrent session detected. Logging out.");
                onForceLogout();
            }
        }
    });
};

export const validateSession = async (userId: string): Promise<boolean> => {
    try {
        const doc = await db.collection('users').doc(userId).get();
        if (!doc.exists) return false;
        const data = doc.data();
        const localSessionId = getLocalSessionId();
        return data?.currentSessionId === localSessionId;
    } catch (e) {
        return true; 
    }
};

// --- Password Reset Utils ---
export const findUserByEmail = async (email: string): Promise<boolean> => {
    const snapshot = await db.collection('users').where('email', '==', email).get();
    return !snapshot.empty;
};

export const verifyRecoveryAnswer = async (email: string, question: string, answer: string): Promise<boolean> => {
    const snapshot = await db.collection('users').where('email', '==', email).get();
    if (snapshot.empty) return false;
    const data = snapshot.docs[0].data();
    return data.recoveryQuestion === question && 
           data.recoveryAnswer?.toLowerCase() === answer.toLowerCase();
};

export const resetPassword = async (email: string, newPassword: string): Promise<boolean> => {
    const snapshot = await db.collection('users').where('email', '==', email).get();
    if (snapshot.empty) return false;

    const doc = snapshot.docs[0];
    const newSessionId = generateSessionId();

    await doc.ref.update({
        password: newPassword,
        currentSessionId: newSessionId
    });
    return true;
};
