                    <p className="text-sm text-green-800">{snapshot.comment}</p>
                  </div>
                )}

                <div className="mb-3">
                  <p className="text-sm text-gray-600">
                    Total Hours Studied: <span className="font-bold text-blue-600">{snapshot.totalTrackedHours.toFixed(1)}h</span>
                  </p>
                </div>

                <div className="space-y-3">
                  {snapshot.trackedVsScheduled.map(item => (
                    <div key={item.subject}>
                      <div className="flex justify-between mb-1">
                        <span className="text-sm font-medium">{item.subject}</span>
                        <span className="text-sm text-gray-600">
                          {item.trackedHours.toFixed(1)}h / {item.scheduledHours.toFixed(1)}h
                        </span>
                      </div>
                      <div className="h-2 bg-gray-200 rounded-full overflow-hidden">
                        <div
                          className="h-full bg-green-500"
                          style={{ width: `${Math.min((item.trackedHours / item.scheduledHours) * 100, 100)}%` }}
                        ></div>
                      </div>
                    </div>
                  ))}
                </div>
              </StatsCard>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

