        const message: Message = { 
            id: Date.now().toString(), 
            sender: userDetails.name, 
            senderProfilePicture: userDetails.profilePicture || null, 
            text: isImage ? '📷 Photo' : `📄 ${file.name}`, 
            image: isImage ? downloadURL : null, 
            fileData: !isImage ? downloadURL : null, 
            fileName: file.name || 'unknown', 
            fileType: file.type || 'application/octet-stream', 
            timestamp: Date.now(), 
            type: isImage ? 'image' : 'file' 
        };
        setShouldAutoScroll(true);
        await db.collection('sessions').doc(sessionCode).update({ messages: firebase.firestore.FieldValue.arrayUnion(message), lastMessage: message, lastActivity: Date.now() });
        await sendSystemMessage(`${userDetails.name} uploaded ${file.name}`);
    } catch (error: any) { 
        console.error(error);
        if (error.code === 'storage/retry-limit-exceeded') {
            addToast("Upload timed out. Please check your connection and try again.", 'error');
        } else {
            addToast("Upload failed.", 'error');
        }
    } finally { setIsUploading(false); if (e.target) e.target.value = ''; }
  };

  const askAI = async () => {
    if (messages.length === 0) { addToast('Start a conversation first!', 'info'); return; }
    if (isViewOnly) return;
    setIsAIThinking(true);
    const conversationContext = messages.slice(-20).map(m => `${m.sender}: ${m.text}`).join('\n');
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY! });
      const prompt = `You are Blay, a study AI. Context:\n${conversationContext}\nResponse:`;
      const response = await ai.models.generateContent({ model: 'gemini-2.5-flash', contents: prompt });
      const aiMessage: Message = { id: Date.now().toString(), sender: 'EduBlay AI', text: response.text, timestamp: Date.now(), type: 'ai', image: null, fileData: null, fileName: null, fileType: null };
      await db.collection('sessions').doc(sessionCode).update({ messages: firebase.firestore.FieldValue.arrayUnion(aiMessage), lastMessage: aiMessage, lastActivity: Date.now() });
    } catch (error) { addToast('AI failed.', 'error'); } finally { setIsAIThinking(false); }
  };

  // --- Navigation & Cleanup ---
  const handleLeaveRequest = () => setShowLeaveConfirm(true);
  const handleConfirmLeave = async () => {
    setShowLeaveConfirm(false);
    if (unsubscribeRef.current) unsubscribeRef.current();
    if (sessionCode && userDetails && !isViewOnly) {
         try {
            await sendSystemMessage(`${userDetails.name} left the session.`, sessionCode);
            const participantToRemove: Participant = { name: userDetails.name, photo: userDetails.profilePicture || null };
            await db.collection('sessions').doc(sessionCode).update({
                participants: firebase.firestore.FieldValue.arrayRemove(participantToRemove),
                participantNames: firebase.firestore.FieldValue.arrayRemove(userDetails.name),
                [`activeParticipants.${userDetails.name}`]: firebase.firestore.FieldValue.delete(),
                [`typing.${userDetails.name}`]: firebase.firestore.FieldValue.delete()
            });
        } catch (e) { }
    }
    setActiveCode(null); setSessionCode(''); setSessionData(null); setMessages([]); setIsSidebarOpen(true);
  };

  useEffect(() => {
    if (sessionCode) {
      if (!isViewOnly) setIsVerifyingConnection(true);
      const unsubscribe = db.collection('sessions').doc(sessionCode)
        .onSnapshot((doc) => {
            if (doc.exists) {
                const data = doc.data() as SessionData;
                setSessionData(data);

                const visibleMessages = (data.messages || []).filter(m => !m.hiddenFor?.includes(userDetails?.name || ''));
                setMessages(visibleMessages);

                if (data.typing && userDetails) {
                    const typers = Object.keys(data.typing).filter(name => name !== userDetails.name && data.typing![name]);
                    setActiveTypers(typers);
                } else { setActiveTypers([]); }

                if (!isViewOnly) {
                    const activeMap = data.activeParticipants || {};
                    const now = Date.now();
                    const activeCount = Object.values(activeMap).filter(ts => now - ts < 60000).length;
                    if (activeCount >= 2) {
                        setIsVerifyingConnection(false);
                        setConnectionSuccess(true);
                    } else {
                        setIsVerifyingConnection(true);
                        setConnectionSuccess(false);
                    }
                }
            } else {
                addToast("Session ended.", 'info');
                setActiveCode(null); setSessionCode(''); setIsSidebarOpen(true);
            }
        });
      unsubscribeRef.current = unsubscribe;
      return () => unsubscribe();
    }
  }, [sessionCode, setActiveCode, userDetails, isViewOnly]); 

  const formatTime = (timestamp: number) => new Date(timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  const getInitials = (name: string) => name ? name.charAt(0).toUpperCase() : '?';
  const getOtherParticipant = (session: SessionData) => {
      if (!userDetails) return null;
      if (session.participants.length > 2) return null; 
      return session.participants.find(p => p.name !== userDetails.name);
  };
  const startEditing = (msg: Message) => { setEditingMessageId(msg.id); setEditMessageText(msg.text); };
  const startDeleting = (msg: Message) => { setMessageToDelete(msg); };

  const filteredHistory = useMemo(() => {
      return sessionHistory.filter(session => {
          const names = session.participants.map(p => p.name).join(' ').toLowerCase();
          return names.includes(searchQuery.toLowerCase()) || session.code.toLowerCase().includes(searchQuery.toLowerCase());
      });
  }, [sessionHistory, searchQuery]);

  return (
    <div className="h-[calc(100vh-90px)] flex bg-white dark:bg-gray-900 rounded-2xl shadow-xl overflow-hidden border dark:border-gray-700 -mx-4 sm:mx-0">
      <div className={`w-full md:w-80 flex-shrink-0 flex flex-col bg-white dark:bg-gray-800 border-r dark:border-gray-700 ${!isSidebarOpen && sessionCode ? 'hidden md:flex' : 'flex'}`}>
        <div className="p-4 bg-gray-50 dark:bg-gray-800/50 border-b dark:border-gray-700 flex justify-between items-center">
            <div className="flex items-center gap-2">
                 {userDetails?.profilePicture ? <img src={userDetails.profilePicture} alt="Me" className="w-10 h-10 rounded-full object-cover" /> : <div className="w-10 h-10 bg-blue-100 dark:bg-blue-900 text-blue-600 rounded-full flex items-center justify-center font-bold">{getInitials(userDetails?.name || '')}</div>}
                <span className="font-bold text-gray-800 dark:text-white truncate max-w-[120px]">{userDetails?.name}</span>
            </div>
            <div className="flex gap-2">
                <button onClick={() => setShowJoinModal(true)} title="Join Session" className="p-2 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full"><Users className="w-5 h-5" /></button>
                <button onClick={() => onActionAttempt(createSession)} title="New Chat" className="p-2 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full"><MessageCircle className="w-5 h-5" /></button>
            </div>
        </div>
        <div className="p-3"><div className="relative"><input type="text" placeholder="Search..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} className="w-full pl-10 pr-4 py-2 bg-gray-100 dark:bg-gray-700 border-none rounded-lg text-sm focus:ring-2 focus:ring-blue-500 text-gray-900 dark:text-white" /><Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" /></div></div>
        <div className="flex-1 overflow-y-auto">
            {filteredHistory.length === 0 ? <div className="p-8 text-center text-gray-500 dark:text-gray-400"><p className="text-sm">No conversations yet.</p></div> : filteredHistory.map((session) => {
                const other = getOtherParticipant(session);
                const isGroup = !other;
                const isActive = session.code === sessionCode;
                return (
                    <div key={session.code} onClick={() => onHistoryItemClick(session)} className={`relative group flex items-center gap-3 p-3 cursor-pointer transition-colors border-b dark:border-gray-700/50 hover:bg-gray-50 dark:hover:bg-gray-700 ${isActive ? 'bg-blue-50 dark:bg-blue-900/20' : ''}`}>
                        <div className="relative flex-shrink-0">{isGroup ? <div className="w-12 h-12 bg-indigo-100 dark:bg-indigo-900 text-indigo-600 rounded-full flex items-center justify-center"><Users className="w-6 h-6" /></div> : other?.photo ? <img src={other.photo} alt={other.name} className="w-12 h-12 rounded-full object-cover" /> : <div className="w-12 h-12 bg-purple-100 dark:bg-purple-900 text-purple-600 rounded-full flex items-center justify-center font-bold text-lg">{getInitials(other?.name || '?')}</div>}</div>
                        <div className="flex-1 min-w-0">
                            <div className="flex justify-between items-baseline"><h4 className="font-semibold text-gray-900 dark:text-gray-100 truncate">{isGroup ? `Group` : other?.name}</h4>{session.lastActivity && <span className="text-[10px] text-gray-500">{new Date(session.lastActivity).toLocaleDateString(undefined, {month: 'short', day: 'numeric'})}</span>}</div>
                            <div className="flex justify-between items-center"><p className="text-sm text-gray-500 dark:text-gray-400 truncate">{session.lastMessage ? (session.lastMessage.type === 'system' ? <span className="italic text-gray-400">{session.lastMessage.text}</span> : session.lastMessage.type === 'image' ? '📷 Photo' : session.lastMessage.text) : <span className="italic">No messages</span>}</p></div>
                        </div>
                        <button onClick={(e) => { e.stopPropagation(); setSessionToDelete(session.code); }} className="absolute right-2 top-1/2 -translate-y-1/2 p-2 text-gray-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"><TrashIcon className="w-4 h-4" /></button>
                    </div>
                );
            })}
        </div>
      </div>

      <div className={`flex-1 flex flex-col bg-[#e5ded8] dark:bg-[#0b141a] ${isSidebarOpen && !activeCode ? 'hidden md:flex' : 'flex'}`}>
        {sessionCode ? (
            <>
                <div className="p-3 bg-white dark:bg-gray-800 border-b dark:border-gray-700 flex items-center justify-between shadow-sm">
                    <div className="flex items-center gap-3">
                        <button onClick={() => setIsSidebarOpen(true)} className="md:hidden p-2 -ml-2 text-gray-600 dark:text-gray-300"><ArrowLeft className="w-5 h-5" /></button>
                        <div className="flex items-center gap-3" onClick={() => copyCode()} title="Copy code">
                             {(() => { const other = sessionData ? getOtherParticipant(sessionData) : null; if(!other) return <div className="w-10 h-10 bg-indigo-100 dark:bg-indigo-900 text-indigo-600 rounded-full flex items-center justify-center"><Users className="w-5 h-5" /></div>; if(other?.photo) return <img src={other.photo} className="w-10 h-10 rounded-full object-cover" alt={other.name} />; return <div className="w-10 h-10 bg-purple-100 dark:bg-purple-900 text-purple-600 rounded-full flex items-center justify-center font-bold">{getInitials(other?.name || '?')}</div>; })()}
                             <div>
                                 <h2 className="font-bold text-gray-900 dark:text-white flex items-center gap-2">{sessionData && (getOtherParticipant(sessionData)?.name || "Group Study")} <span className="text-xs font-normal px-2 py-0.5 bg-gray-200 dark:bg-gray-700 rounded-full text-gray-600 dark:text-gray-300 select-all">{sessionCode}</span> {isViewOnly && <span className="text-[10px] bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full font-bold">VIEW ONLY</span>}</h2>
                                 <p className="text-xs text-gray-500 dark:text-gray-400">{sessionData?.participants.map(p => p.name).join(', ')}</p>
                             </div>
                        </div>
                    </div>
                    <div className="flex items-center gap-4">
                        <div className="flex flex-col items-center">
                            <button onClick={askAI} disabled={isAIThinking || isViewOnly} className="p-2 text-purple-600 hover:bg-purple-50 dark:hover:bg-gray-700 rounded-full disabled:opacity-50"><Sparkles className={`w-5 h-5 ${isAIThinking ? 'animate-spin' : ''}`} /></button>
                            <span className="text-[9px] text-gray-500 dark:text-gray-400">Ask AI</span>
                        </div>
                         <div className="flex flex-col items-center">
                            <button onClick={handleLeaveRequest} className="p-2 text-red-500 hover:bg-red-50 dark:hover:bg-gray-700 rounded-full"><LogOut className="w-5 h-5" /></button>
                            <span className="text-[9px] text-gray-500 dark:text-gray-400">Exit</span>
                        </div>
                    </div>
                </div>

                <div 
                    ref={scrollContainerRef}
                    onScroll={handleScroll}
                    className="flex-1 overflow-y-auto p-4 space-y-4 relative bg-[url('https://user-images.githubusercontent.com/15075759/28719144-86dc0f70-73b1-11e7-911d-60d70fcded21.png')] dark:bg-[url('https://user-images.githubusercontent.com/15075759/28719144-86dc0f70-73b1-11e7-911d-60d70fcded21.png')] bg-repeat"
                >
                    {isVerifyingConnection && !isViewOnly && (
                        <div className="absolute inset-0 z-10 backdrop-blur-md bg-white/60 dark:bg-black/60 flex flex-col items-center justify-center text-center p-6">
                             <div className="w-24 h-24 bg-white dark:bg-gray-800 rounded-full shadow-2xl flex items-center justify-center mb-6 animate-pulse border-4 border-blue-500"><Users className="w-10 h-10 text-blue-500" /></div>
                             <h3 className="text-2xl font-bold text-gray-800 dark:text-white mb-2">Waiting for Partner...</h3>
                             <p className="text-gray-600 dark:text-gray-300 max-w-sm mb-6">The session is locked until your partner enters the code.</p>
                             <div className="bg-white dark:bg-gray-800 px-6 py-3 rounded-xl shadow-lg border border-gray-200 dark:border-gray-700"><p className="text-xs text-gray-500 dark:text-gray-400 uppercase tracking-widest mb-1">Pairing Code</p><p className="text-3xl font-mono font-bold text-gray-900 dark:text-white tracking-widest">{sessionCode}</p></div>
                             <button onClick={() => shareCode(sessionCode)} className="mt-8 flex items-center gap-2 text-blue-600 dark:text-blue-400 font-semibold hover:underline"><Share2 className="w-4 h-4" /> Share Code Again</button>
                        </div>
                    )}
                    {messages.map((msg) => {
                        const isMe = msg.sender === userDetails?.name;
                        const isEditing = editingMessageId === msg.id;
                        return (
                            <div key={msg.id} className={`flex ${isMe ? 'justify-end' : 'justify-start'} ${msg.type === 'ai' || msg.type === 'system' ? 'justify-center' : ''}`}>
                                {msg.type === 'system' ? <div className="bg-gray-200/80 dark:bg-gray-800/80 px-4 py-1 rounded-full shadow-sm text-xs font-semibold text-gray-600 dark:text-gray-300 my-2">{msg.text}</div> : msg.type === 'ai' ? <div className="bg-white/90 dark:bg-gray-800/90 backdrop-blur-sm p-4 rounded-xl shadow-sm max-w-lg border-t-4 border-purple-500 text-sm"><div className="flex items-center gap-2 mb-1 font-bold text-purple-600"><Bot className="w-4 h-4" /> EduBlay AI</div><p className="text-gray-800 dark:text-gray-200 whitespace-pre-wrap">{msg.text}</p></div> : <div className={`flex max-w-[80%] sm:max-w-[60%] group relative ${isMe ? 'flex-row-reverse' : 'flex-row'}`}>
                                    <div className={`relative p-2 rounded-lg shadow-sm text-sm ${isMe ? 'bg-[#d9fdd3] dark:bg-[#005c4b] text-gray-900 dark:text-gray-100 rounded-tr-none' : 'bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100 rounded-tl-none'}`}>
                                        {!isMe && <p className="text-xs font-bold text-orange-600 mb-1">{msg.sender}</p>}
                                        {msg.type === 'image' && <img src={msg.image || ''} alt="Shared" className="rounded-md max-w-full max-h-60 object-cover mb-1" />}
                                        {msg.type === 'file' && <div className="flex items-center gap-3 p-2 bg-black/5 dark:bg-white/10 rounded-md mb-1"><FileText className="w-8 h-8 text-blue-500" /><div className="flex-1 min-w-0 overflow-hidden"><p className="truncate font-medium">{msg.fileName}</p><p className="text-xs opacity-70 uppercase">{msg.fileType?.split('/')[1]}</p></div><a href={msg.fileData || '#'} download={msg.fileName} target="_blank" rel="noreferrer" className="p-1.5 bg-white dark:bg-gray-700 rounded-full shadow-sm"><Download className="w-4 h-4" /></a></div>}
                                        {isEditing ? <div className="min-w-[200px]"><textarea value={editMessageText} onChange={(e) => setEditMessageText(e.target.value)} className="w-full p-2 rounded border border-blue-300 dark:border-blue-700 bg-white dark:bg-gray-900 text-black dark:text-white text-sm focus:outline-none focus:ring-2 focus:ring-blue-500" rows={3}/><div className="flex justify-end gap-2 mt-2"><button onClick={() => setEditingMessageId(null)} className="p-1 text-red-500 hover:bg-red-100 dark:hover:bg-red-900/30 rounded"><X className="w-4 h-4"/></button><button onClick={() => handleEditMessage(msg.id, editMessageText)} className="p-1 text-green-500 hover:bg-green-100 dark:hover:bg-green-900/30 rounded"><CheckIcon className="w-4 h-4"/></button></div></div> : (msg.text && <p className="whitespace-pre-wrap leading-relaxed">{msg.text}</p>)}
                                        <div className={`text-[10px] mt-1 text-right ${isMe ? 'text-gray-500 dark:text-gray-300' : 'text-gray-500'}`}>{formatTime(msg.timestamp)}{isMe && <span className="ml-1 text-blue-500">✓</span>}</div>
                                    </div>
                                    {!isEditing && !isViewOnly && <div className={`absolute top-0 ${isMe ? 'right-full mr-2' : 'left-full ml-2'} flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity bg-white/80 dark:bg-black/80 backdrop-blur-sm rounded-lg p-1 shadow-sm`}>
                                        {isMe && msg.type === 'text' && <button onClick={() => startEditing(msg)} className="p-1.5 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-md text-gray-600 dark:text-gray-300" title="Edit"><PencilIcon className="w-4 h-4" /></button>}
                                        <button onClick={() => {navigator.clipboard.writeText(msg.text); addToast('Copied!', 'success');}} className="p-1.5 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-md text-gray-600 dark:text-gray-300" title="Copy"><CopyIcon className="w-4 h-4" /></button>
                                        {msg.type === 'text' && <button onClick={() => handleSaveToNotes(msg.text)} className="p-1.5 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-md text-gray-600 dark:text-gray-300" title="Save to Notes"><SaveIcon className="w-4 h-4" /></button>}
                                        {isMe && <button onClick={() => startDeleting(msg)} className="p-1.5 hover:bg-red-100 dark:hover:bg-red-900/30 rounded-md text-red-500 hover:text-red-600" title="Delete"><Trash2 className="w-4 h-4" /></button>}
                                    </div>}
                                </div>}
                            </div>
                        );
                    })}
                    {activeTypers.length > 0 && !isVerifyingConnection && <div className="flex justify-start animate-fade-in-up mb-2"><div className="bg-white/90 dark:bg-gray-800/90 backdrop-blur rounded-full px-4 py-2 shadow-sm text-xs font-semibold text-gray-500 dark:text-gray-400 flex items-center gap-1 border border-gray-200 dark:border-gray-700"><span className="w-1.5 h-1.5 bg-gray-400 dark:bg-gray-500 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></span><span className="w-1.5 h-1.5 bg-gray-400 dark:bg-gray-500 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></span><span className="w-1.5 h-1.5 bg-gray-400 dark:bg-gray-500 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></span><span className="ml-2">{activeTypers.join(', ')} {activeTypers.length === 1 ? 'is' : 'are'} typing...</span></div></div>}
                    <div ref={messagesEndRef} />
                </div>

                <div className="p-3 bg-gray-100 dark:bg-gray-800 flex items-center gap-2 relative">
                    {showEmojiPicker && !isVerifyingConnection && !isViewOnly && <div className="absolute bottom-full left-0 mb-2 bg-white dark:bg-gray-800 p-3 rounded-xl shadow-xl border dark:border-gray-700 grid grid-cols-6 gap-2 emoji-picker-container z-50 w-64">{COMMON_EMOJIS.map(emoji => <button key={emoji} onClick={() => handleEmojiClick(emoji)} className="text-2xl hover:bg-gray-100 dark:hover:bg-gray-700 rounded p-1 transition-colors">{emoji}</button>)}</div>}

                    <button onClick={() => fileInputRef.current?.click()} className="p-2 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200 disabled:opacity-50" disabled={isUploading || isVerifyingConnection || isViewOnly}><Upload className="w-6 h-6" /></button>
                    <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" accept="image/*,application/pdf,application/vnd.ms-powerpoint,application/vnd.openxmlformats-officedocument.presentationml.presentation" />

                    <button onClick={() => setShowEmojiPicker(!showEmojiPicker)} className="emoji-picker-container p-2 text-gray-500 hover:text-yellow-500 dark:text-gray-400 dark:hover:text-yellow-400 disabled:opacity-50" disabled={isVerifyingConnection || isViewOnly}><Smile className="w-6 h-6" /></button>

                    <div className="flex-1 flex items-center">
                        <input 
                            type="text" 
                            value={newMessage} 
                            onChange={handleInputChange} 
                            onKeyPress={(e) => e.key === 'Enter' && sendMessage()} 
                            placeholder={isVerifyingConnection ? "Waiting for partner..." : (isViewOnly ? "View Only Mode" : isListening ? "Listening..." : "Type a message")} 
                            disabled={isVerifyingConnection || isViewOnly || isListening} 
                            className={`flex-1 px-4 py-2 bg-transparent border-none focus:ring-0 text-gray-900 dark:text-white placeholder-gray-500 disabled:opacity-50 text-lg ${isListening ? 'italic text-blue-500' : ''}`} 
                        />
                    </div>

                    <button 
                        onClick={toggleDictation}
                        className={`p-2 rounded-full shadow-sm transition-all ${isListening ? 'bg-red-500 text-white animate-pulse shadow-red-300' : 'bg-blue-500 text-white hover:bg-blue-600'} disabled:opacity-50`}
                        disabled={isVerifyingConnection || isViewOnly}
                    >
                        <Mic className="w-5 h-5" />
                    </button>

                    {newMessage.trim() && !isListening && (
                        <button onClick={sendMessage} disabled={isVerifyingConnection || isViewOnly} className="p-2 bg-green-600 text-white rounded-full hover:bg-green-700 disabled:opacity-50 disabled:bg-gray-400 shadow-sm">
                            <Send className="w-5 h-5" />
                        </button>
                    )}
                </div>
            </>
        ) : (
            <div className="flex-1 flex flex-col items-center justify-center bg-gray-100 dark:bg-gray-900 text-center p-8 border-b-8 border-green-500">
                <div className="w-40 h-40 bg-white dark:bg-gray-800 rounded-full flex items-center justify-center shadow-xl mb-6"><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/6/6b/WhatsApp.svg/1200px-WhatsApp.svg.png" alt="Connect" className="w-24 h-24 opacity-80 grayscale" style={{ filter: 'grayscale(100%) opacity(0.5)' }} /></div>
                <h1 className="text-3xl font-light text-gray-700 dark:text-gray-200 mb-4">EduBlay Connect</h1>
                <p className="text-gray-500 dark:text-gray-400 max-w-md">Send and receive messages, share study materials, and collaborate with AI assistance in real-time.</p>
                <div className="mt-8 flex items-center gap-2 text-sm text-gray-400"><LockIcon className="w-3 h-3" /> End-to-end encrypted connection</div>
            </div>
        )}
      </div>
      {createdSessionCode && <div className="fixed inset-0 bg-black/70 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-fade-in-down"><div className="bg-white dark:bg-gray-800 rounded-2xl shadow-2xl w-full max-w-md p-6 border dark:border-gray-700 relative"><button onClick={() => setCreatedSessionCode(null)} className="absolute top-4 right-4 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"><X className="w-6 h-6" /></button><div className="text-center mb-6"><div className="w-16 h-16 bg-green-100 dark:bg-green-900/30 rounded-full flex items-center justify-center mx-auto mb-4"><Share2 className="w-8 h-8 text-green-600 dark:text-green-400" /></div><h3 className="text-2xl font-bold text-gray-800 dark:text-white">Invite a Friend</h3><p className="text-gray-600 dark:text-gray-400 mt-2">Share this unique code with your friend so they can join your study session.</p></div><div className="bg-gray-100 dark:bg-gray-700 rounded-xl p-4 mb-6 flex items-center justify-between border border-gray-200 dark:border-gray-600"><span className="text-2xl font-mono font-bold text-gray-800 dark:text-white tracking-widest">{createdSessionCode}</span><div className="flex gap-2"><button onClick={() => copyCode(createdSessionCode)} className="p-2 hover:bg-white dark:hover:bg-gray-600 rounded-lg transition-colors text-gray-600 dark:text-gray-300" title="Copy Code"><CopyIcon className="w-5 h-5" /></button><button onClick={() => shareCode(createdSessionCode)} className="p-2 hover:bg-white dark:hover:bg-gray-600 rounded-lg transition-colors text-gray-600 dark:text-gray-300" title="Share Link"><Share2 className="w-5 h-5" /></button></div></div><button onClick={handleStartChattingClick} className="w-full py-3 bg-green-600 text-white font-bold rounded-xl shadow-lg hover:bg-green-700 transition-all">Start Chatting</button></div></div>}
