});

const useColorTheme = () => ({ colorTheme: 'default' });

const timeToMinutes = (time: string): number => {
  const [hours, minutes] = time.split(':').map(Number);
  return hours * 60 + minutes;
};

// Mock Gemini service
const generateWeeklyProgressComment = async (userDetails: UserDetails, data: any): Promise<string> => {
  await new Promise(resolve => setTimeout(resolve, 500));
  const totalTracked = data.reduce((sum: number, item: any) => sum + item.trackedHours, 0);
  const totalScheduled = data.reduce((sum: number, item: any) => sum + item.scheduledHours, 0);
  const percentage = totalScheduled > 0 ? ((totalTracked / totalScheduled) * 100).toFixed(0) : 0;

  if (totalTracked === 0) return "No study sessions tracked this week. Let's get started!";
  if (Number(percentage) >= 90) return `Excellent work! You've completed ${percentage}% of your study goals. Keep up the momentum!`;
  if (Number(percentage) >= 70) return `Good progress! You've achieved ${percentage}% of your study plan. A few more sessions and you'll hit your target.`;
  return `You've completed ${percentage}% of your study goals. There's still time to catch up!`;
};

