const DonutChart: React.FC<{ data: { type: string; value: number; color: string }[] }> = ({ data }) => {
  const { t } = useLanguage();
  const total = data.reduce((sum, item) => sum + item.value, 0);
  if (total === 0) return <div className="text-gray-500 text-center">{t('progression.noData')}</div>;

  const radius = 80;
  const circumference = 2 * Math.PI * radius;
  let accumulatedPercentage = 0;

  return (
    <svg viewBox="0 0 200 200" className="w-full max-w-xs mx-auto">
      {data.map((item, index) => {
        if (item.value === 0) return null;
        const percentage = item.value / total;
        const strokeDasharray = `${percentage * circumference} ${circumference}`;
        const strokeDashoffset = -accumulatedPercentage * circumference;
        accumulatedPercentage += percentage;
        return (
          <circle
            key={index}
            cx="100"
            cy="100"
            r={radius}
            fill="none"
            stroke={item.color}
            strokeWidth="40"
            strokeDasharray={strokeDasharray}
            strokeDashoffset={strokeDashoffset}
            transform="rotate(-90 100 100)"
          />
        );
      })}
    </svg>
  );
};

const Progression: React.FC<{
