    const checkAndSaveWeeklySnapshot = async () => {
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const todayStr = today.toISOString().split('T')[0];

      // Check if we've already processed today
      if (todayStr === lastCheckedDate) return;
      setLastCheckedDate(todayStr);

      const dayOfWeek = today.getDay();

      // Check if it's Sunday (end of week) or Monday (start of new week)
      if (dayOfWeek === 0 || dayOfWeek === 1) {
        // Calculate last week's date range
        const daysToSubtract = dayOfWeek === 0 ? 7 : 8; // If Sunday, go back 7 days; if Monday, go back 8
        const lastWeekEnd = new Date(today);
        lastWeekEnd.setDate(today.getDate() - (dayOfWeek === 0 ? 1 : 2));

        const lastWeekStart = new Date(lastWeekEnd);
        lastWeekStart.setDate(lastWeekEnd.getDate() - 6);

        // Get tracked data for last week
        const lastWeekData = trackedData.filter(session => {
          const parts = session.date.split('-').map(Number);
          if (parts.length !== 3) return false;
          const [year, month, day] = parts;
          const sessionDate = new Date(year, month - 1, day);
          return sessionDate >= lastWeekStart && sessionDate <= lastWeekEnd;
        });

        if (lastWeekData.length > 0 && plan) {
          // Calculate scheduled hours from plan
          const studyBySubject = new Map<string, number>();
          for (const day of plan) {
            for (const slot of day.slots) {
              if (!slot.startTime || !slot.endTime) continue;
              const duration = timeToMinutes(slot.endTime) - timeToMinutes(slot.startTime);
              if (duration <= 0) continue;
              if (slot.type === ActivityType.STUDY) {
                studyBySubject.set(slot.activity, (studyBySubject.get(slot.activity) || 0) + duration);
              }
            }
          }

          // Calculate tracked hours
          const trackedBySubject = new Map<string, number>();
          lastWeekData.forEach(session => {
            trackedBySubject.set(session.subject, (trackedBySubject.get(session.subject) || 0) + session.durationMinutes);
          });

          const allSubjects = Array.from(new Set([...Array.from(studyBySubject.keys()), ...Array.from(trackedBySubject.keys())]));
          const trackedVsScheduled = allSubjects.map(subject => ({
            subject,
            scheduledHours: (studyBySubject.get(subject) || 0) / 60,
            trackedHours: (trackedBySubject.get(subject) || 0) / 60,
          }));

          const totalTrackedHours = lastWeekData.reduce((sum, s) => sum + s.durationMinutes, 0) / 60;

          // Generate comment
          let comment = '';
