const ChartRenderer: React.FC<{ config: any; height?: number }> = ({ config, height = 300 }) => {
    const canvasRef = useRef<HTMLCanvasElement | null>(null);
    const chartInstanceRef = useRef<any | null>(null);

    useEffect(() => {
        if (canvasRef.current) {
            // Destroy existing chart if it exists
            if (chartInstanceRef.current) {
                chartInstanceRef.current.destroy();
            }

            const Chart = (window as any).Chart;
            if (Chart) {
                const ctx = canvasRef.current.getContext('2d');
                if (ctx) {
                    // Apply global defaults for better visuals
                    Chart.defaults.font.family = "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial";
                    Chart.defaults.color = document.documentElement.classList.contains('dark') ? '#9ca3af' : '#4b5563';

                    chartInstanceRef.current = new Chart(ctx, config);
                }
            }
        }
        return () => {
            if (chartInstanceRef.current) {
                chartInstanceRef.current.destroy();
                chartInstanceRef.current = null;
            }
        };
    }, [config]);

    return (
        <div style={{ height: `${height}px`, width: '100%', position: 'relative' }}>
            <canvas ref={canvasRef} />
        </div>
    );
};

