              }
            }
          }

          const trackedBySubject = new Map<string, number>();
          lastWeekData.forEach(session => {
            trackedBySubject.set(session.subject, (trackedBySubject.get(session.subject) || 0) + session.durationMinutes);
          });

          const allSubjects = Array.from(new Set([...Array.from(studyBySubject.keys()), ...Array.from(trackedBySubject.keys())]));
          const trackedVsScheduled = allSubjects.map(subject => ({
            subject,
            scheduledHours: (studyBySubject.get(subject) || 0) / 60,
            trackedHours: (trackedBySubject.get(subject) || 0) / 60,
          }));

          const totalTrackedHours = lastWeekData.reduce((sum, s) => sum + s.durationMinutes, 0) / 60;

          let comment = '';
          if (userDetails) {
            try {
              comment = await generateWeeklyProgressComment(userDetails, trackedVsScheduled);
            } catch (error) {
              console.error('Failed to generate comment:', error);
            }
          }

          const snapshot: WeeklySnapshot = {
            weekStart: lastWeekStart.toISOString().split('T')[0],
            weekEnd: lastWeekEnd.toISOString().split('T')[0],
            trackedVsScheduled,
            totalTrackedHours,
            comment
          };

          const exists = weeklySnapshots.some(s => s.weekStart === snapshot.weekStart);
          if (!exists) {
            const updatedSnapshots = [...weeklySnapshots, snapshot];
            setWeeklySnapshots(updatedSnapshots);
            localStorage.setItem('weekly-snapshots', JSON.stringify(updatedSnapshots));
          }
        }
      }
    };

    if (plan && trackedData.length > 0) {
      checkAndSaveWeeklySnapshot();
    }
  }, [trackedData, plan, userDetails, lastCheckedDate, weeklySnapshots]);

  const stats = useMemo(() => {
    if (!plan) return null;

    const totals = { study: 0, lecture: 0, agenda: 0, break: 0, free: 0 };
    const studyBySubject = new Map<string, number>();
    const dailyTotals = new Map<string, number>();

    for (const day of plan) {
      let dayStudyMinutes = 0;
      for (const slot of day.slots) {
        if (!slot.startTime || !slot.endTime) continue;
        const duration = timeToMinutes(slot.endTime) - timeToMinutes(slot.startTime);
        if (duration <= 0) continue;

        const activityType = slot.type || ActivityType.FREE;

        switch (activityType) {
          case ActivityType.STUDY:
            totals.study += duration;
            studyBySubject.set(slot.activity, (studyBySubject.get(slot.activity) || 0) + duration);
            dayStudyMinutes += duration; // Only count study hours for daily chart
            break;
          case ActivityType.LECTURE:
            totals.lecture += duration;
            break;
          case ActivityType.AGENDA:
            totals.agenda += duration;
            break;
          case ActivityType.BREAK:
            totals.break += duration;
            break;
          case ActivityType.FREE:
            totals.free += duration;
            break;
        }
      }
      dailyTotals.set(day.day, dayStudyMinutes);
    }

    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const dayOfWeek = today.getDay();
    const diffToMonday = dayOfWeek === 0 ? 6 : dayOfWeek - 1;
    const startOfWeek = new Date(today);
    startOfWeek.setDate(today.getDate() - diffToMonday);
    const endOfWeek = new Date(startOfWeek);
    endOfWeek.setDate(startOfWeek.getDate() + 6);
    endOfWeek.setHours(23, 59, 59, 999);

    const weeklyTrackedData = trackedData.filter(session => {
        const parts = session.date.split('-').map(Number);
        if (parts.length !== 3) return false;
        const [year, month, day] = parts;
        const sessionDate = new Date(year, month - 1, day);
        return sessionDate >= startOfWeek && sessionDate <= endOfWeek;
    });

    const trackedStudyBySubject = new Map<string, number>();
    weeklyTrackedData.forEach(session => {
        trackedStudyBySubject.set(session.subject, (trackedStudyBySubject.get(session.subject) || 0) + session.durationMinutes);
    });

    const scheduledSubjects = Array.from(studyBySubject.keys());
    const trackedSubjects = Array.from(trackedStudyBySubject.keys());
    const allSubjects = Array.from(new Set([...scheduledSubjects, ...trackedSubjects]));

    const trackedVsScheduled = allSubjects.map(subject => ({
        subject,
        scheduledHours: parseFloat(((studyBySubject.get(subject) || 0) / 60).toFixed(1)),
        trackedHours: parseFloat(((trackedStudyBySubject.get(subject) || 0) / 60).toFixed(1)),
    }));

    return {
      totalHours: {
        study: (totals.study / 60).toFixed(1),
        lecture: (totals.lecture / 60).toFixed(1),
        agenda: (totals.agenda / 60).toFixed(1),
        break: (totals.break / 60).toFixed(1),
        free: (totals.free / 60).toFixed(1),
      },
      dailyHours: DAYS_OF_WEEK.map(day => ({
        day: day.slice(0, 3),
        hours: parseFloat(((dailyTotals.get(day) || 0) / 60).toFixed(1))
      })),
      activityDistribution: [
        totals.study, totals.lecture, totals.agenda, totals.break, totals.free
      ].map(m => parseFloat((m / 60).toFixed(1))),
      trackedVsScheduled,
    };
  }, [plan, trackedData, t]);

  useEffect(() => {
    if (stats?.trackedVsScheduled && userDetails) {
      const hasTrackedData = stats.trackedVsScheduled.some(item => item.trackedHours > 0);
      if (hasTrackedData) {
        setIsCommentLoading(true);
        generateWeeklyProgressComment(userDetails, stats.trackedVsScheduled)
          .then(comment => setWeeklyComment(comment))
          .catch(() => setWeeklyComment(''))
          .finally(() => setIsCommentLoading(false));
      } else {
        setWeeklyComment('');
        setIsCommentLoading(false);
      }
    } else {
        setIsCommentLoading(false);
    }
  }, [stats?.trackedVsScheduled, userDetails]);

  if (!plan || !stats) {
    return (
      <div className="max-w-4xl mx-auto bg-white dark:bg-gray-900 rounded-2xl shadow-lg p-6 md:p-10 text-center">
        <h2 className="text-2xl font-bold text-gray-800 dark:text-white mb-4">{t('progression.title')}</h2>
        <p className="text-gray-500 dark:text-gray-400">{t('progression.noPlan')}</p>
      </div>
    );
  }

  const themeColorHex = getThemeColor(colorTheme);
  const isDarkMode = document.documentElement.classList.contains('dark');
  const textColor = isDarkMode ? '#e5e7eb' : '#374151';
  const gridColor = isDarkMode ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.1)';

  // --- CHART CONFIGURATIONS ---

  // 1. Daily Scheduled Hours (Bar Chart)
  const dailyChartConfig = {
      type: 'bar',
      data: {
          labels: stats.dailyHours.map(d => d.day),
          datasets: [{
              label: t('progression.activity.study'),
              data: stats.dailyHours.map(d => d.hours),
              backgroundColor: themeColorHex,
              borderRadius: 6,
              barThickness: 24,
          }]
      },
      options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
              legend: { display: false },
              tooltip: {
                  backgroundColor: isDarkMode ? '#1f2937' : '#ffffff',
                  titleColor: isDarkMode ? '#f9fafb' : '#111827',
                  bodyColor: isDarkMode ? '#f9fafb' : '#111827',
                  borderColor: gridColor,
                  borderWidth: 1,
                  padding: 10,
              }
          },
          scales: {
              y: {
                  beginAtZero: true,
                  grid: { color: gridColor },
                  ticks: { color: textColor }
              },
              x: {
                  grid: { display: false },
                  ticks: { color: textColor }
              }
          }
      }
  };

  // 2. Tracked vs Scheduled (Grouped Bar Chart)
  const subjects = stats.trackedVsScheduled.map(i => i.subject);
  const trackedVsScheduledConfig = {
      type: 'bar',
      data: {
          labels: subjects.length > 0 ? subjects : [t('progression.noData')],
          datasets: [
              {
                  label: t('progression.legend.scheduled'),
                  data: subjects.length > 0 ? stats.trackedVsScheduled.map(i => i.scheduledHours) : [],
                  backgroundColor: '#94a3b8', // Grayish for scheduled
                  borderRadius: 4,
                  barPercentage: 0.6,
                  categoryPercentage: 0.8
              },
              {
                  label: t('progression.legend.tracked'),
                  data: subjects.length > 0 ? stats.trackedVsScheduled.map(i => i.trackedHours) : [],
                  backgroundColor: '#22c55e', // Green for tracked
                  borderRadius: 4,
                  barPercentage: 0.6,
                  categoryPercentage: 0.8
              }
          ]
      },
      options: {
          responsive: true,
          maintainAspectRatio: false,
          indexAxis: 'y', // Horizontal bars for better course name readability
          plugins: {
              legend: { position: 'top', labels: { color: textColor } },
              tooltip: {
                backgroundColor: isDarkMode ? '#1f2937' : '#ffffff',
                titleColor: isDarkMode ? '#f9fafb' : '#111827',
                bodyColor: isDarkMode ? '#f9fafb' : '#111827',
                borderColor: gridColor,
                borderWidth: 1,
              }
          },
          scales: {
              x: {
                  grid: { color: gridColor },
                  ticks: { color: textColor }
              },
              y: {
                  grid: { display: false },
                  ticks: { color: textColor, autoSkip: false }
              }
          }
      }
  };

  // 3. Activity Breakdown (Doughnut)
  const activityConfig = {
      type: 'doughnut',
      data: {
          labels: [
              t('progression.activity.study'),
              t('progression.activity.lecture'),
              t('progression.activity.agenda'),
              t('progression.activity.break'),
              t('progression.activity.free')
          ],
          datasets: [{
              data: stats.activityDistribution,
              backgroundColor: [
                  '#3b82f6', // Study
                  '#a855f7', // Lecture
                  '#f472b6', // Agenda
                  '#22c55e', // Break
                  '#9ca3af'  // Free
              ],
              borderWidth: 0,
              hoverOffset: 4
          }]
      },
      options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
              legend: { position: 'right', labels: { color: textColor, usePointStyle: true } }
          },
          cutout: '70%'
      }
  };


  return (
    <div className="max-w-7xl mx-auto space-y-8">
       <div>
         <h2 className="text-3xl font-bold text-gray-800 dark:text-white">{t('progression.title')}</h2>
         <p className="text-gray-500 dark:text-gray-400 mt-1">{t('progression.subtitle')}</p>
       </div>

       <StatsCard title={t('progression.weeklyInsight.title')}>
        <div className="flex items-start gap-4">
          <div className="flex-shrink-0 bg-primary/10 text-primary dark:bg-primary/20 dark:text-primary-light rounded-full p-3">
             <GeminiIcon className="w-6 h-6" />
          </div>
          <div>
            {isCommentLoading ? (
              <p className="text-gray-500 dark:text-gray-400 italic">{t('progression.weeklyInsight.loading')}</p>
            ) : weeklyComment ? (
              <p className="text-gray-700 dark:text-gray-300">{weeklyComment}</p>
            ) : (
              <p className="text-gray-500 dark:text-gray-400">{t('progression.weeklyInsight.noData')}</p>
            )}
          </div>
        </div>
      </StatsCard>

       <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <StatsCard title={t('progression.weeklyOverview')} className="lg:col-span-1">
                <div className="space-y-4">
                    <div><p className="text-sm text-gray-500 dark:text-gray-400">{t('progression.totalStudy')}</p><p className="font-bold text-2xl text-study">{stats.totalHours.study}h</p></div>
                    <div><p className="text-sm text-gray-500 dark:text-gray-400">{t('progression.totalLecture')}</p><p className="font-bold text-lg text-lecture">{stats.totalHours.lecture}h</p></div>
                    <div><p className="text-sm text-gray-500 dark:text-gray-400">{t('progression.personalAgenda')}</p><p className="font-bold text-lg text-agenda">{stats.totalHours.agenda}h</p></div>
                    <div><p className="text-sm text-gray-500 dark:text-gray-400">{t('progression.totalBreak')}</p><p className="font-bold text-lg text-break">{stats.totalHours.break}h</p></div>
                    <div><p className="text-sm text-gray-500 dark:text-gray-400">{t('progression.totalFree')}</p><p className="font-bold text-lg text-free">{stats.totalHours.free}h</p></div>
                </div>
            </StatsCard>

            <StatsCard title={t('progression.activityBreakdown')} className="lg:col-span-2">
                <ChartRenderer config={activityConfig} height={250} />
            </StatsCard>
       </div>

        <div className="grid grid-cols-1 gap-6">
             <StatsCard title={t('progression.trackedVsScheduled')}>
                 {/* Horizontal bar chart for better course readability */}
                 <ChartRenderer config={trackedVsScheduledConfig} height={400} />
             </StatsCard>

             <StatsCard title={t('progression.dailyScheduled')}>
                 <ChartRenderer config={dailyChartConfig} height={300} />
            </StatsCard>
        </div>

        {/* Weekly History */}
        {weeklySnapshots.length > 0 && (
          <div>
            <h3 className="text-2xl font-bold mb-4 text-gray-800 dark:text-white">{t('progression.weeklyHistory')}</h3>
            <div className="space-y-6">
              {weeklySnapshots.slice().reverse().map((snapshot) => (
                <StatsCard 
                  key={snapshot.weekStart}
                  title={`${t('progression.week')}: ${snapshot.weekStart} to ${snapshot.weekEnd}`}
                >
                  {snapshot.comment && (
                    <div className="bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-700 rounded-lg p-3 mb-4 flex items-start gap-2">
                      <GeminiIcon />
                      <p className="text-sm text-green-800 dark:text-green-300">{snapshot.comment}</p>
                    </div>
                  )}

                  <div className="mb-4">
                    <p className="text-sm text-gray-600 dark:text-gray-400">
                      Total Hours Studied: <span className="font-bold text-green-600 dark:text-green-400">{snapshot.totalTrackedHours.toFixed(1)}h</span>
                    </p>
                  </div>
                   {/* We can render a static summary bar here if needed, but for now simple stats are clean */}
                </StatsCard>
              ))}
            </div>
          </div>
        )}
    </div>
  );
};

export default Progression;
